pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small dead space) with non-linear penalty
    let pr = post_residual as f64;
    score += pr * pr / (bin_capacity as f64 * 2.0);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving dead space the next item cannot use
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize placing into bins when many bins fit (prefer spreading toward best fit)
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Time horizon: early in stream, be more conservative (favor new bins for large items);
    // late in stream, fill open bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Global state coupling: high mean residual means open bins are roomy;
    // prefer filling them rather than opening new bins
    score -= mean_residual * 0.15;

    // Many open bins: discourage opening another
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate logic: empty bin gets base cost; make it attractive only
    // when item is large relative to capacity or residuals are tight
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let tight_state = (mean_residual < item_size as f64) as f64;
        score = 45.0 + large_item * 40.0 - tight_state * 30.0 - progress * 15.0
              - (post_residual as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 80.0; // don't open new bin when an existing bin is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Tiered dead-space penalty, progress-amplified (finer near zero).
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.0 } else if post_residual < 8 { 6.4 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);

    // Quadratic dead-space pressure, fragmentation-scaled.
    if post_residual > 0 {
        score += (0.04 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 270.0;
    }

    // Lookahead: exact / tight fit rewards, penalize gaps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 8.0 + 6.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
