                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        if next_item_size > 0 && (item_size as u64 + 2 * next_item_size as u64) == bin_capacity as u64 {
            score -= 26.0 * (1.0 - 0.5 * progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.6 {
            score += 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf >= mean_residual {
            score -= 4.0 * (1.0 - progress) * (prf / cap).min(0.4);
        }
        // Fresh-bin economy: opening a bin is only worth it when the leftover
        // it strands is smaller than the average stranded slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream consolidation: prefer chain-friendly post-residuals.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Scarcity-adjusted opening — when few bins can host the item,
        // opening a fresh bin is relatively cheap; when many can, prefer reuse.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Pair-completion opening — if the fresh bin's leftover pairs with the
        // mean residual toward full capacity, reward.
        if post_residual > 0 && (prf + mean_residual - cap).abs() <= 6.0 {
            score -= 11.0;
        }
        // Triple-chain opening — a fresh bin whose leftover can absorb the
        // next two items exactly is nearly free to open.
        if next_item_size > 0
            && (item_size as u64 + 3 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
        {
            score -= 18.0 * (1.0 - 0.4 * progress);
        }
        // Stranded-leftover guard — opening a bin that strands a leftover
        // just below the next item's size wastes the tightest usable window.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        // Residual-floor opening — when opening a fresh bin, prefer
        // post-residuals that sit just above the next item so the leftover
        // stays chain-usable; penalize leftovers that overshoot widely.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 4.5 * overshoot * (0.5 + 0.5 * progress);
        }
        // Big-item fresh-bin preference — large items arriving when the
        // mean residual cannot host them should open fresh bins cheaply.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 7.0 * (item_frac - 0.45) * 4.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty — the fewer bins can host the
    // item, the more valuable it is to leave a *usable* leftover.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty — leftovers in the awkward band just
    // below half the mean residual are rarely reusable; penalize them
    // proportionally to stream progress.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation — bins already near full should absorb the
    // item if the resulting leftover remains chain-usable; this compacts
    // nearly-full bins instead of scattering fill across many bins.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement — when the post-residual matches a
    // small multiple of the next item, close the bin aggressively; this
    // reduces dead space by draining bins that can be finished cleanly.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive — near the end of the stream, any
    // nonzero leftover on an existing bin should be strongly penalized so
    // remaining items drain residual space instead of opening fresh bins.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // Quadratic dead-space ramp — amplify the cost of medium-size
    // leftovers (the main source of wasted bins) with a smooth nonlinear
    // term that peaks in the awkward 8–25 band and fades for large ones
    // that remain chain-usable.
    if post_residual > 0 {
        let band_center = 16.0;
        let width = 14.0;
        let bump = 1.0 - ((prf - band_center) / width).powi(2);
        if bump > 0.0 {
            score += 5.5 * bump * (prf / cap) * (0.6 + 0.8 * progress);
        }
    }

    // Two-item exact-closure lookahead — when the next item plus a
    // plausible follow-up (mean residual proxy) exactly closes this bin,
    // reward strongly; this drives chains that finish bins completely.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let diff = (rem2 as f64 - mean_residual).abs();
        if diff <= 2.0 {
            score -= 7.0 * (1.0 - diff / 3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-harvest scarcity — when few bins fit the item and an
    // open bin's leftover after placement stays below the next item, that
    // stranded sliver is pure waste; penalize it more sharply so the item
    // flows to bins whose leftover remains harvestable.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 3 {
        score += 6.0 * (1.0 - prf / next_item_size as f64) * (1.0 - progress);
    }

    // NEW: bin-drain priority — when many open bins compete and this bin's
    // pre-placement residual is the smallest among plausible hosts, reward
    // filling it first so nearly-full bins are flushed early, keeping the
    // open-bin population's residual distribution tight and chainable.
    if bin_residual < bin_capacity && open_bins_count > 3 {
        let fill_rank = 1.0 - (bin_residual as f64 / mean_residual.max(1.0)).min(1.0);
        score -= 3.5 * fill_rank * (0.4 + 0.6 * progress) * (1.0 - item_frac);
    }

    // NEW: residual-split guard — avoid placements that chop a large
    // reusable residual into two fragments neither of which can host the
    // next item; such splits convert one usable window into dead space.
    if post_residual > 0 && next_item_size > 0 && bin_residual > next_item_size * 2 {
        let split_waste = if post_residual < next_item_size && bin_residual - item_size < next_item_size {
            1.0
        } else {
            0.0
        };
        if split_waste > 0.0 {
            score += 4.5 * (1.0 - progress) * (1.0 - item_frac);
        }
    }

    // NEW: capacity-aware leftover value — leftovers in the range that a
    // typical item (mean residual scale) can still consume are assets, not
    // waste; discount the generic dead-space penalty for them.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 4 {
        score -= 3.0 * (1.0 - progress) * (prf / cap).min(0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.0 } else if post_residual < 8 { 6.4 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 270.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (prf / cap);
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        if next_item_size > 0 && (item_size as u64 + 2 * next_item_size as u64) == bin_capacity as u64 {
            score -= 26.0 * (1.0 - 0.5 * progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.6 {
            score += 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf >= mean_residual {
            score -= 4.0 * (1.0 - progress) * (prf / cap).min(0.4);
        }
        // Fresh-bin economy: opening a bin is only worth it when the leftover
        // it strands is smaller than the average stranded slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream consolidation: prefer chain-friendly post-residuals.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Scarcity-adjusted opening — when few bins can host the item,
        // opening a fresh bin is relatively cheap; when many can, prefer reuse.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Pair-completion opening — if the fresh bin's leftover pairs with the
        // mean residual toward full capacity, reward.
        if post_residual > 0 && (prf + mean_residual - cap).abs() <= 6.0 {
            score -= 11.0;
        }
        // Triple-chain opening — a fresh bin whose leftover can absorb the
        // next two items exactly is nearly free to open.
        if next_item_size > 0
            && (item_size as u64 + 3 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
        {
            score -= 18.0 * (1.0 - 0.4 * progress);
        }
        // Stranded-leftover guard — opening a bin that strands a leftover
        // just below the next item's size wastes the tightest usable window.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        // Residual-floor opening — when opening a fresh bin, prefer
        // post-residuals that sit just above the next item so the leftover
        // stays chain-usable; penalize leftovers that overshoot widely.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 4.5 * overshoot * (0.5 + 0.5 * progress);
        }
        // Big-item fresh-bin preference — large items arriving when the
        // mean residual cannot host them should open fresh bins cheaply.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 7.0 * (item_frac - 0.45) * 4.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty — the fewer bins can host the
    // item, the more valuable it is to leave a *usable* leftover.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty — leftovers in the awkward band just
    // below half the mean residual are rarely reusable; penalize them
    // proportionally to stream progress.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation — bins already near full should absorb the
    // item if the resulting leftover remains chain-usable; this compacts
    // nearly-full bins instead of scattering fill across many bins.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement — when the post-residual matches a
    // small multiple of the next item, close the bin aggressively; this
    // reduces dead space by draining bins that can be finished cleanly.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive — near the end of the stream, any
    // nonzero leftover on an existing bin should be strongly penalized so
    // remaining items drain residual space instead of opening fresh bins.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // Quadratic dead-space ramp — amplify the cost of medium-size
    // leftovers (the main source of wasted bins) with a smooth nonlinear
    // term that peaks in the awkward 8–25 band and fades for large ones
    // that remain chain-usable.
    if post_residual > 0 {
        let band_center = 16.0;
        let width = 14.0;
        let bump = 1.0 - ((prf - band_center) / width).powi(2);
        if bump > 0.0 {
            score += 5.5 * bump * (prf / cap) * (0.6 + 0.8 * progress);
        }
    }

    // Two-item exact-closure lookahead — when the next item plus a
    // plausible follow-up (mean residual proxy) exactly closes this bin,
    // reward strongly; this drives chains that finish bins completely.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let diff = (rem2 as f64 - mean_residual).abs();
        if diff <= 2.0 {
            score -= 7.0 * (1.0 - diff / 3.0) * (1.0 - 0.5 * progress);
        }
    }

    // Residual-harvest scarcity — when few bins fit the item and an
    // open bin's leftover after placement stays below the next item, that
    // stranded sliver is pure waste; penalize it more sharply so the item
    // flows to bins whose leftover remains harvestable.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 3 {
        score += 6.0 * (1.0 - prf / next_item_size as f64) * (1.0 - progress);
    }

    // Bin-drain priority — when many open bins compete and this bin's
    // pre-placement residual is the smallest among plausible hosts, reward
    // filling it first so nearly-full bins are flushed early, keeping the
    // open-bin population's residual distribution tight and chainable.
    if bin_residual < bin_capacity && open_bins_count > 3 {
        let fill_rank = 1.0 - (bin_residual as f64 / mean_residual.max(1.0)).min(1.0);
        score -= 3.5 * fill_rank * (0.4 + 0.6 * progress) * (1.0 - item_frac);
    }

    // Residual-split guard — avoid placements that chop a large
    // reusable residual into two fragments neither of which can host the
    // next item; such splits convert one usable window into dead space.
    if post_residual > 0 && next_item_size > 0 && bin_residual > next_item_size * 2 {
        let split_waste = if post_residual < next_item_size && bin_residual - item_size < next_item_size {
            1.0
        } else {
            0.0
        };
        if split_waste > 0.0 {
            score += 4.5 * (1.0 - progress) * (1.0 - item_frac);
        }
    }

    // Capacity-aware leftover value — leftovers in the range that a
    // typical item (mean residual scale) can still consume are assets, not
    // waste; discount the generic dead-space penalty for them.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 4 {
        score -= 3.0 * (1.0 - progress) * (prf / cap).min(0.3);
    }

    // NEW: multi-step drain projection — estimate how many consecutive
    // next-sized items this bin's post-residual can absorb; the deeper the
    // chain, the more valuable the placement, with an extra bonus when the
    // chain terminates exactly (no stranded sliver at the end).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let chain_len = (post_residual / next_item_size) as f64;
        let chain_tail = (post_residual % next_item_size) as f64;
        let depth_bonus = 2.8 * chain_len.min(5.0) / 5.0;
        let tail_cost = 3.5 * (chain_tail / next_item_size.max(1) as f64) * (0.4 + 0.6 * progress);
        score -= depth_bonus * (1.0 - progress);
        score += tail_cost;
        if chain_tail == 0.0 {
            score -= 4.5 * (1.0 - 0.5 * progress);
        }
    }

    // NEW: harvest-vs-open arbitration — when several bins fit the item
    // but none of their post-residuals can host the next item while a
    // fresh bin's leftover would, tilt toward opening a new bin; the
    // reverse tilt pushes toward draining the best existing host.
    if next_item_size > 0 && open_bins_count > 2 {
        let next_f = next_item_size as f64;
        let fresh_leftover = cap - item_size as f64;
        let fresh_hosts_next = fresh_leftover >= next_f;
        if bin_residual < bin_capacity && post_residual < next_item_size && fresh_hosts_next {
            // This bin would strand the next item, a fresh bin would not:
            // penalize this host so the fresh-bin candidate wins instead.
            score += 7.0 * (1.0 - progress) * (1.0 - (prf / next_f).min(1.0));
        } else if bin_residual < bin_capacity && post_residual >= next_item_size && fresh_leftover < next_f && fresh_leftover < post_residual as f64 {
            // This bin keeps a chainable leftover while a fresh bin would
            // strand the next item: reward draining this host.
            score -= 6.0 * (1.0 - progress) * ((post_residual as f64 - fresh_leftover) / cap).min(0.4);
        }
    }

    // NEW: residual-band calibration — sharpen the dead tiers by adding a
    // fine-grained sawtooth that penalizes leftovers just below common
    // item sizes (multiples of 5), which are the hardest windows to fill.
    if post_residual > 0 && post_residual < 50 {
        let band_pos = post_residual % 5;
        if band_pos != 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 1.6 * (band_pos as f64 / 5.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Refined dead-space tiers with steeper wall near zero + quadratic pressure.
    let dead = if post_residual < 4 { 9.6 } else if post_residual < 8 { 6.6 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Lookahead shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 240.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 7.0 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 10.0 + 7.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 20.0;
            }
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 5.0 * (1.0 - rem2 as f64 / cap);
            }
            if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
                score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.5 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Tight-bin preference.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.8 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 18.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 9.0;
        }
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 34.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 22.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 26.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        // Fresh-bin economy: penalize bins stranding worse-than-average slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream chain-friendly leftovers.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Mid-band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }

    // Global waste pressure.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 6.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Squander guard: strand-mismatch penalty scaled by fragmentation.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / next_item_size as f64).min(1.0));
    }

    // Residual-pool absorption check.
    if post_residual > 0 && open_bins_count > 6 && prf < mean_residual * 0.5 {
        score += 4.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Next-item mismatch penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;

    // Perfect closure reward (strengthened).
    if post_residual == 0 {
        score -= 300.0;
    }

    // Tiered dead-space penalty (steeper near zero).
    let dead = if post_residual < 5 { 9.0 } else if post_residual < 10 { 6.0 } else if post_residual < 16 { 3.6 } else if post_residual < 20 { 2.6 } else if post_residual < 40 { 0.7 } else { 0.0 };
    score += dead * prf;

    // Continuous quadratic dead-space pressure.
    if post_residual > 0 {
        score += 0.05 * prf * prf / cap;
    }

    // Structured residual rewards (divisible leftovers are reusable).
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 45.0;
    }

    // Lookahead: exact / tight fit shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 240.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 18.0 * (1.0 - rem2 as f64 / cap) + 7.0 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 10.0 + 7.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 20.0;
            }
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 5.0 * (1.0 - rem2 as f64 / cap);
            }
            if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
                score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.5 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.8 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 10.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 36.0;
        score += 30.0 * waste_ratio - 14.0 * fragmentation - 24.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 18.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 18.0;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 9.0;
        }
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 34.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 22.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 26.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 16.0 + 10.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 11.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 15.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.5 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 11.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 13.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_size as f64 / cap < 0.4 {
            score += 8.0 * (1.0 - item_size as f64 / cap);
        }
        if post_residual > 0 && next_item_size > 0 && prf < next_item_size as f64 && prf <= mean_residual {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Mid-stream awkward band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 7.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += prf / cap * 52.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 26.0 * (progress - 0.75);
        }
    }

    // Global waste pressure after early stream.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 7.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.5 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.5 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 12.0;
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.5 * (1.0 + progress);
    }

    // Compaction pull toward exact closure when fits are scarce.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 5.0 + 6.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Variance-aware tightness.
    let frag_index = mean_residual / cap;
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.5 * frag_index * (prf / cap);
    }

    // NEW: residual-pool absorption check — if the item could be absorbed by
    // the aggregate mean slack of the open portfolio, mildly discourage
    // placements that strand tiny residuals.
    if post_residual > 0 && open_bins_count > 6 && prf < mean_residual * 0.5 {
        score += 4.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0));
    }

    score
}

