}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += poly * 2.0;

    // Penalize large post_residual more as stream progresses (less time to fill gaps)
    score += (pr_norm * pr_norm * pr_norm) * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr) / cap * 0.5;
    }

    // Discourage proliferation of open bins with big residuals
    score += (mean_residual / cap) * (open_bins_count as f64).ln().max(1.0) * 0.2;

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.6 + progress * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (10/20/25/50) are reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 6.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 4.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= reusable;

    // Penalize dead space in awkward classes: 1..9 leftover is nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division threshold on post_residual: large leftovers are good bins to fill.
    let big_leftover = post_residual / 30; // 0,1,2,3
    score += big_leftover as f64 * 2.0;

    // Lookahead coupling: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item also leaves a harmonic residual?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score += (next_post % 10) as f64 * 0.3;
        } else {
            // next item cannot fit here; slight penalty if this bin is the only option
            if fitting_bins_count == 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of a new bin equals capacity - item_size).
    if bin_residual == bin_capacity {
        // penalty grows with number of open bins that could have taken the item
        score += (fitting_bins_count as f64) * 10.0;
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // if item is small, opening a new bin wastes capacity
        if item_size < 40 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter packs)
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.05;
    }

    // Modulo harmony between item and residual: item divides residual evenly -> clean split
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Medium gaps (10..=19) are only usable by small future items: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage opening yet another one.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Base cost of opening a bin, growing with the number of already open bins.
        score += 30.0 + 6.0 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin is acceptable: soften the cost.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // If the next item would fit exactly in a fresh bin, encourage opening it.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 50.0;
        }
    } else {
        // Reward using existing bins when they are already fairly full.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would fit but would leave a dead gap, penalize slightly.
    if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
        score += 12.0;
    }

    // Late in the stream, avoid opening new bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for bins whose residual is close to the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).

    // Aggressive 2-step lookahead: perfect match with next item is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item will NOT fit here: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // waste is bad; leaving less is good.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize tiny unusable leftovers (dead space < 10 can never fit a min item).
    if post_residual < 10 {
        score += 30.0;
    }

    // Early in the stream, keep bins open/consolidated; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 15.0 - 20.0 * desperation;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize small-but-unusable leftovers: dead space that can't hold even a small item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 + 0.5 * (next_item_size as f64);
        } else {
            // Penalize creating a gap that just misses the next item.
            let miss = (next_item_size as f64) - (post_residual as f64);
            if miss < 10.0 {
                score += 5.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual of open bins.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits.
        score += 4.0;
        // Opening new bins is more attractive when many bins are open but residuals are scattered.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 {
            // Open bins have little usable space; a new bin is reasonable.
            score -= 3.0 + 2.0 * progress;
        }
        // Late in the stream, prefer consolidating into open bins.
        if progress > 0.8 {
            score += 5.0;
        }
    }

    // Slight preference for bins below mean residual (balance fragmentation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * (residual_f - mean_residual) / (bin_capacity as f64);
    }

    // Reward filling bins closer to capacity as stream progresses.
    let fill_ratio = (bin_capacity as f64 - residual_f) / (bin_capacity as f64);
    score -= 2.0 * fill_ratio * (step_index as f64 / (total_items.max(1) as f64));

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: tight fit preferred (small post_residual), with non-linear squashing
    let tightness = (pr / cap).powi(2) + 0.35 * (pr / cap).powi(4);
    let mut score = 60.0 * tightness;

    // Smooth stream-progress coupling: early on, prefer filling bins tighter (waste less);
    // later, slightly relax toward using open bins rather than spawning new ones.
    let progress_coupling = 1.0 + 0.5 * progress * (1.0 - progress) * 4.0
        + 0.3 * progress.powi(2);
    score *= progress_coupling;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead = if pr > 0.0 {
        let r = pr / cap;
        r * (1.0 - r) * (1.0 - r) // peaks for mid-small unusable residuals
    } else { 0.0 };
    score += 25.0 * dead;

    // Reward exact or near-exact fits smoothly
    score -= 15.0 * (-pr as f64 / 8.0).exp();

    // Lookahead: bonus if next item fits the post residual (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (-gap * 6.0).exp();
    } else if next_item_size > 0 {
        score += 4.0 * (next_ratio - pr / cap).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate large spaces)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev.max(0.0) + 2.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = 45.0 + 20.0 * openness - 30.0 * fit_ratio * (1.0 + progress);
        // If the item is large, a fresh bin is natural
        score += 10.0 * fit_ratio;
        // If no open bin fits well (post_residual huge relative), new bin less penalized
        score -= 15.0 * (fit_ratio - 0.5).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets capture "usable leftover" granularity.
    let post_class = post_residual % 10;
    // Reward post-residuals that are exactly 0 (perfect fit) heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space in awkward classes (1..9 leftover is hard to reuse).
        if post_class > 0 && post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        }
        // Integer-division thresholds: leftover divisible by 10 is a "harmonic" slot.
        if post_class == 0 {
            score -= 8.0;
        }
    }

    // Fractional capacity coupling: how much of the bin is consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 15.0;

    // Lookahead harmony: does post_residual match the next item exactly, or at least fit it?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // chain-perfect: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0; // next item cannot reuse this bin's leftover
        }
        // Modulo coupling between post_residual and next item size classes.
        if next_item_size % 10 == post_class && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bins are attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base; add penalty that shrinks when existing bins are fragmented.
        let fragmentation = (mean_residual - cap) / cap;
        if fragmentation.abs() < 0.05 && open_bins_count > 0 {
            score += 5.0; // open bins are all fresh; opening another adds little
        } else if post_residual == 0 {
            score -= 5.0;
        }
        // Slight preference for new bins early in the stream (room to build harmonic classes).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 3.0;
    }

    // Scale by open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it costly unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is attractive only if it enables a perfect fit later.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover space; mild penalty proportional to waste.
        score += post_residual as f64 * 0.3;
    }

    // Late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect chain: next item exactly fills the post residual.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post residual -> excellent chaining.
        else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward closeness of the chain fit (small slack is best).
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if the chain leaves a residual still in the usable small-item range.
            if slack <= 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit here: this bin becomes dead space after placement.
            let dead = post_residual as f64;
            // Penalize dead space, but less if it is tiny (nearly perfect fit now).
            score += 0.5 * dead;
            if dead > 10.0 {
                score += 10.0;
            }
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual deviates favorably from the mean: packing into
    // bins with below-average residual (tight bins) keeps large gaps available.
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    score += 0.15 * dev;

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && !is_new_bin {
        // This is the only open bin that fits; opening a new bin would waste
        // this residual entirely. Strongly favor using it.
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // A fresh bin is only attractive when the item is large relative to
        // typical residuals or no open bin fits well. Base cost of opening a bin.
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is at least as big, a fresh bin keeps flexibility.
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            // No open bin fits at all: new bin is mandatory, drop the penalty.
            score -= 40.0;
        }
    }

    // --- Progress-based tightening ---
    // As the stream progresses, be more conservative with residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // --- Wasted-capacity term: residual that only tiny items could use ---
    if post_residual > 0 && post_residual < 10 {
        // Post residual below the minimum item size is pure waste.
        score -= 20.0; // but a near-perfect fill is great, so reward it
    }
    if post_residual >= 10 && post_residual < 20 {
        // Small but usable residual: mildly penalize to prefer tighter fits.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic decay of post-residual dead space.
    score -= 1.5 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: strongly reward bins where the next item also fits (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tight = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - chain_tight / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residual too small for the known next item.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: penalize sloppy fits more strongly.
        score += 0.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state: if mean residual is low, conserve open bins; if high, prefer spreading.
    let mr = mean_residual / bin_capacity as f64;
    score -= 8.0 * (mr - 0.5) * (post_residual as f64 / bin_capacity as f64 - mr);

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the open-bin count is high (fragmentation control).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 10.0; // forced new bin anyway
        } else {
            // Opening a new bin is good if the item is large and few bins fit it.
            let large_item = item_size as f64 / bin_capacity as f64;
            score += 30.0 * (1.0 - large_item) * (fitting_bins_count as f64 / (fitting_bins_count as f64 + 2.0));
            score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * large_item;
        }
    }

    // Mild penalty on opening bins when few bins exist (early stream) unless item huge.
    if open_bins_count < 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // As stream progresses, increasingly reward small post_residuals (tight packing).
    score -= (norm_pr * norm_pr) * 30.0 * (0.5 + progress);
    score -= (norm_pr * norm_pr * norm_pr) * 20.0 * prog2;

    // Early stream: mild preference for spreading load (favor larger residuals slightly).
    score += (1.0 - progress) * (1.0 - progress) * norm_pr * 8.0;

    // Penalize dead space that no plausible item can fill (smooth non-linear term).
    let max_item = 100.0f64;
    if pr > 0.0 {
        let unusable = ((pr - max_item) / max_item).max(0.0);
        score += unusable * unusable * 50.0;
    }

    // Perfect fit reward, amplified with progress.
    if post_residual == 0 {
        score -= 40.0 * (1.0 + progress);
    }

    // Last-chance bin bonus (only bin that fits): avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth decay).
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        score -= fits_next * closeness * 12.0 * (1.0 + progress);
        // Penalize leaving residual that matches next item exactly but wastes capacity marginally.
        score += (1.0 - fits_next) * (next_item_size as f64 / bin_capacity as f64) * 6.0;
    }

    // New-bin candidate handling: discourage opening new bins unless current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 20.0 * (1.0 - progress);
        // Allow new bin when existing residuals are all poor fits.
        let waste = (post_residual as f64) / bin_capacity as f64;
        score -= waste * waste * 10.0;
    }

    // Mild penalty proportional to open bin count to encourage consolidation.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean (consolidate small residuals).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fraction of capacity wasted after placement.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 60.0;

    // Dead-space penalty: post_residual too small to hold any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // tiny unusable sliver
    }

    // Harmonic class logic on post_residual via integer division thresholds.
    let class = post_residual / 10; // coarse capacity-fraction class (0..10)
    // Mid classes (residual 30..70) are reusable; extremes are less valuable.
    let class_bonus: f64 = match class {
        0 => 30.0,          // 0-9: dead space
        1 => 10.0,          // 10-19
        2 => -5.0,          // 20-29
        3 => -12.0,         // 30-39
        4 => -15.0,         // 40-49
        5 => -15.0,         // 50-59
        6 => -12.0,         // 60-69
        7 => -6.0,          // 70-79
        8 => 4.0,           // 80-89
        9 => 12.0,          // 90-99 (nearly full, fine)
        _ => 0.0,
    };
    score += class_bonus;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item granularities (10, 20, 25) are more likely reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: mild penalty so we only open new bins when existing ones fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0 - 40.0 * waste_frac; // waste_frac == 1 here, so net positive
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - waste_frac);

    // Prefer filling bins when many bins are open (reduce bin count).
    score += open_bins_count as f64 * 0.3 * waste_frac;

    // Tie-break toward bins whose residual is close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

