    let pressure = open_bins_count as f64 * 0.5;
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += pressure * (1.0 - tightness);

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or the item fits poorly everywhere; penalize default new-bin otherwise.
    if bin_residual == bin_capacity {
        score += 30.0;
