        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 20.0;
        }
    }

    // Prefer bins with larger current residual consumed efficiently (avoid fragmenting small-residual bins)
    if bin_residual < item_size * 2 && bin_residual >= item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
