        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates below the mean residual (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more open to starting new bins;
    // late in the stream, pack tightly and avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as the stream progresses.
        score += 5.0 + 25.0 * progress;
        // Allow a new bin early if it's very crowded already.
        if open_bins_count > 8 && progress < 0.3 {
            score -= 10.0;
        }
    } else {
        score -= 4.0 * (1.0 - progress); // favor existing bins early
    }

    // Mild penalty for proliferating open bins.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
