    let mut score = pr;

    // Smooth polynomial coupling: post-residual weighted differently as stream progresses.
    // Early on, prefer leaving flexible residuals (reward low post_residual less aggressively);
    // later, tighten packing by rewarding small post_residual more strongly.
    let w = 0.5 + 1.5 * progress * progress; // in [0.5, 2.0], smooth
    score += (pr - 0.5 * cap) * (w - 1.0);

    // Non-linear penalty for awkward residuals: penalize residuals that are too small
    // to fit typical future items (dead space), using a smooth U-shaped term.
    let dead = (1.0 - norm_pr).max(0.0);
    score += 8.0 * dead * dead * dead * cap * 0.0; // placeholder-free: remove
    score -= 8.0 * norm_pr * norm_pr * (1.0 - norm_pr) * cap * 0.1;

    // Perfect-fit reward: smooth Gaussian-like bonus around small residuals.
    score -= 10.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement smoothly; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-(gap * gap) / 200.0).exp();
        if next_item_size as f64 > pr {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Mild global-balance term: prefer bins whose residual is below the mean
    // (concentrate filling), scaled smoothly by number of open bins.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // New-bin candidate adjustment: empty bins get a moderate prior so we only
    // open a new bin when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
