    // Mild preference for tighter bins overall (smaller residual before placement).
    score += bin_residual as f64 * 0.05;

    // Tie-break with mean residual divergence: prefer bins below mean residual
    // (already fragmented) to absorb the item.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
