        if item_size <= 25 {
            score += 20.0;
        }
        // Large item: fresh bin is safer than fragmenting.
        if item_size as f64 / cap > 0.6 {
            score -= 18.0;
        }
        // Fresh-bin two-pack play: item + next exactly fills a new bin.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 45.0;
        }
        // Fresh-bin near-perfect two-pack.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap > 0 && gap <= 6 {
                score -= 18.0;
            }
        }
        // Three-pack lookahead with next item twice.
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 22.0 * (1.0 - progress);
        }
        // Many open bins with sufficient mean residual: opening wastes capacity.
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 12.0 * (mean_residual - item_size as f64) / cap;
        }
        // Avoid stranding a tiny residual in an existing bin when a fresh one exists.
        if prf > 0 && prf < 12 && open_bins_count > 2 {
            score += 14.0 + 10.0 * (1.0 - progress);
