    // Near-perfect match: next item fits with small slack (<= 6).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 520.0 * (1.0 - slack / 6.0).max(0.0);
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 && rem2 % 5 == 0 {
            score -= 12.0 * (1.0 - progress);
        } else if rem2 > 0 && rem2 < 8 {
            score += 20.0 * progress;
