    }
    // Penalize if next item cannot fit into post_residual.
    else if next_item_size > 0 && next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += 2.2 * gap * (1.0 - 0.4 * progress);
        // Small-gap value scaling: tiny residual that next item misses.
        if post_residual > 0 && post_residual < 8 {
