    if post_residual > 0 {
        let dead = if post_residual < 5 { 7.0 } else if post_residual < 10 { 4.8 } else if post_residual < 20 { 2.4 } else if post_residual < 40 { 0.6 } else { 0.0 };
        score += dead * prf;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 1.2 * (20.0 - prf);
