        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 70.0 + 3.0 * fitting_bins_count as f64;
        score += 20.0 * waste_ratio - 12.0 * frag - 22.0 * progress + size_bias;
        // Small items fit anywhere; fresh bin is wasteful for them.
        if item_size <= 30 {
            score += 17.0;
        }
        // Large item: fresh bin is safer than fragmenting.
        if item_size as f64 / cap > 0.65 {
            score -= 18.0;
        }
        // Large item + fragmented portfolio: fresh bin is safer.
        if item_size as f64 / cap > 0.5 && frag > 0.35 {
            score -= 8.0;
        }
        // Fresh-bin two-pack play: item + next exactly fills a new bin.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 45.0;
        }
        // Fresh-bin near-perfect two-pack.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
