    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    // MUTATION: adaptive dead-space scaling by stream phase — early on, small
    // leftovers are riskier (many items still coming), so amplify the wall;
    // late in the stream relax it to prefer any placement that closes bins.
    if post_residual > 0 && post_residual < 20 {
        score += (1.0 - progress) * 6.0 * (20 - post_residual) as f64 / 20.0;
    }

    // MUTATION: portfolio-fit awareness — when several bins fit, prefer the one
