        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 45.0;
        }
        // Fresh-bin near-perfect two-pack.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap > 0 && gap <= 5 {
                score -= 20.0;
            }
        }
        // Three-pack lookahead with next item twice.
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        // Many open bins with sufficient mean residual: opening wastes capacity.
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 12.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 8 && frag > 0.5 {
            score -= 12.0;
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        // Avoid stranding a tiny residual in an existing bin when a fresh one exists.
        if prf > 0 && prf < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Slack-per-bin waste signal: abundant portfolio slack discourages fresh bin.
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        // Fresh-bin leftover should not be awkward relative to next item.
        if next_item_size > 0 && prf > 0 {
            let gap_to_next = if prf >= next_item_size as f64 {
                prf - next_item_size as f64
            } else {
                (next_item_size as f64 - prf) * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.25;
    }

    // High open-bin count: keep portfolio balanced around mean residual.
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.45 * dev;
    }

    // Chained-fit residuals: residual divisible by next item keeps options open.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    // Late-stream: close out nearly-full bins.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Awkward mid-band shaping early on.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable common residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 25 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Waste-ratio mismatch coupling with lookahead.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Usability-weighted leftover: small unusable leftovers early are costly.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    // Near-miss cascade: residual barely above next item keeps future options perfect.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Two-step lookahead: reward residuals that absorb next item and leave reusable remainder.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    // Dead-space avoidance under fragmentation.
    if post_residual > 0 && post_residual < 15 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // Composable residual shaping away from the half-capacity band.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Scarcity discount.
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Residual reuse horizon: leftover only valuable if next item can consume it.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    // Late-stream compaction: avoid stranding unusable residual with many bins open.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Dead-space penalty: refined tiers with steeper wall near zero,
    // plus a smooth continuous component on top of tiers.
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.2 } else if post_residual < 20 { 2.6 } else if post_residual < 40 { 0.7 } else { 0.0 };
