        }
        if open_bins_count > 8 && frag > 0.5 {
            score -= 12.0;
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        // Never strand a tiny residual in an existing bin when a fresh one exists.
        if prf > 0 && prf < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Fresh-bin residual pairability with portfolio mean.
        if prf > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
    }

    // Prefer tighter bins (small residual before placement).
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.2;
    }

    // High open-bin count: keep portfolio balanced around mean residual.
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.4 * dev;
    }

    // Chained-fit residuals: residual divisible by next item keeps options open.
    if next_item_size > 0 && prf > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    // Late-stream: close out nearly-full bins.
    if prf > 0 && prf <= 4 && progress > 0.55 {
        score -= 12.0;
    }

    // Awkward mid-band shaping early on.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable common residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 25 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Waste-ratio mismatch coupling with lookahead.
    if prf > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Usability-weighted leftover.
    if prf > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    // Near-miss cascade: residual barely above next item keeps future options perfect.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Two-step lookahead: reward residuals that absorb next item and leave reusable remainder.
    if next_item_size > 0 && post_residual >= next_item_size && prf > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    // Dead-space avoidance under fragmentation.
    if prf > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // Scarcity discount.
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // NEW: dead-space variance pressure — strand mid-band leftovers when spread is high.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // NEW: late-stream exactness — push toward zero or reusable residuals at stream end.
    if progress > 0.75 && prf > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

