    }

    // Prefer tighter bins with fill-ratio refinement.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.2;
    }

    // High open-bin count: keep portfolio balanced.
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.4 * dev;
    }

    // Chained-fit residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    // Late-stream: close out nearly-full bins.
    if post_residual > 0 && post_residual <= 4 && progress > 0.55 {
        score -= 12.0;
    }

    // Awkward mid-band shaping early on.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable common residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 25 || post_residual == 30 {
