        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.2 * pair_gap / cap;
        }
        // NEW: fresh-bin residual should be absorbable by the *next* item's
        // size class — if the leftover is smaller than the next item and
        // small, opening a fresh bin strands capacity; penalize harder early.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - progress);
