    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.2 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.5 + 6.5 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.2 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && open_bins_count > 3 {
        score -= 3.5 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.5 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.5 * (progress - 0.75) * 4.0;
        }
    }

    // NEW: endgame squeeze — in the final stretch, favor any placement that
    // closes a bin completely, since stranded residuals become pure waste.
    if progress > 0.9 && post_residual == 0 {
        score -= 20.0;
    }

    // NEW: dual-fit coupling — a residual that both the next item AND the
    // mean portfolio residual could partially absorb is extra valuable.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if (after as f64) >= mean_residual * 0.5 && after > 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let prf = post_residual as f64;
