        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((post_residual as f64 + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // NEW: prefer opening a fresh bin when the residual left behind is a
        // plausible item size (1..=100 band) and near the running mean item
        // scale implied by mean_residual — leftovers matching future demand.
        if post_residual > 0 {
            let plausibility = if post_residual <= 100 { 1.0 - (post_residual as f64 / 100.0) } else { 0.0 };
            score += 5.0 * (1.0 - plausibility) - 3.0 * plausibility;
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((post_residual as f64 - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = post_residual as f64 / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - post_residual as f64 / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - post_residual as f64) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (post_residual as f64 / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 3.0 / fitting_bins_count as f64;
    }

    // NEW: dead-space ratio coupling — amplify the quadratic dead-space
    // pressure when the portfolio is already fragmented, so placements
    // stranding unusable slivers are punished harder mid/late stream.
    if post_residual > 0 && open_bins_count > 3 {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += (prf * prf / cap) * 0.05 * frag * (0.5 + progress);
    }

    // NEW: residual-horizon compaction — a leftover is only worth keeping if
    // it can be consumed by the next item OR falls in the highly reusable
    // small band (<= 10); penalize stranded mid-band leftovers that neither
    // the next item nor small future items can absorb.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 10 {
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Dead-space penalty: refined tiers with steeper wall near zero,
    // sharpened at the 4/8/12 boundaries to punish strandable slivers.
    let dead = if post_residual < 4 { 9.5 } else if post_residual < 8 { 7.0 } else if post_residual < 12 { 5.0 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * (post_residual as f64);
    // Continuous quadratic dead-space pressure for mid-range leftovers.
    let prf = post_residual as f64;
    if post_residual > 0 {
        score += 0.04 * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 40.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 14.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (post_residual as f64 / cap);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        // Large item + fragmented portfolio: fresh bin is safer.
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        // Never strand a residual smaller than the smallest plausible item.
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Fresh bin two-pack play.
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        // Three-pack lookahead — if next two items could stack in a fresh bin.
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        // When many bins are open and mean residual already exceeds this item,
        // opening a new bin wastes capacity — discourage.
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        // Fresh-bin placement should prefer items that leave a residual
        // matching the next item's size class band; penalize awkward leftovers.
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        // Avoid opening a fresh bin for tiny items when portfolio slack
        // is abundant; slack per open bin is a direct waste signal.
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        // Fresh-bin residual "pairability" — a leftover is good if it can
        // pair with the mean residual of the portfolio to absorb future items.
        if post_residual > 0 {
            let pair_gap = ((post_residual as f64 + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        // Fresh-bin residual should be absorbable by the next item's
        // size class in one or two steps; penalize leftovers the next item
        // cannot even partially consume.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // NEW: fresh-bin "triple absorbability" — a fresh-bin leftover is only
        // worth opening if the next item can consume it and still leave a
        // remainder that the mean-residual class can plug; otherwise prefer
        // consolidating into existing open bins.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 as f64 > mean_residual * 1.3 {
                score += 7.0 * (rem2 as f64 / cap) * (0.5 + progress);
            }
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    // Dead-space avoidance under fragmentation (band tightened to 16).
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // Late-stream compaction.
    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // Reward chained-fit residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((post_residual as f64 - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Mid-stream awkward-band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Scarcity discount.
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Two-step lookahead: reward residuals that can absorb next item AND leave
    // a reusable remainder; penalize residuals that leave nothing usable after.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    // High open-bin count: keep portfolio balanced around mean residual.
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Waste-ratio coupling: penalize placements whose leftover fraction
    // matches neither the next item nor a common divisor band.
    if post_residual > 0 {
        let leftover_frac = post_residual as f64 / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Usability-weighted leftover — leftover is valuable only if some open
    // bin portfolio suggests items of that size still appear.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - post_residual as f64 / 25.0) * (1.0 - progress);
        }
    }

    // Exact-fill cascade bonus — residual that equals next_item_size plus a
    // tiny amount keeps future options nearly perfect; reward the near-miss band.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Residual reuse horizon — a leftover is only worth keeping if the
    // next item can actually consume it; scale penalty by how far off it is.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    // Encourage near-full bins to reach exact closure when the next item
    // is small enough to plug the gap — mild compaction pull.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    // Dead-space variance pressure — when the portfolio residual spread
    // is high, extra-punish placements that strand mid-band (15..35) leftovers,
    // steering toward either tight closure or generous reusable slack.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - post_residual as f64) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Late-stream exactness — as the stream ends, push harder toward
    // zero or perfectly reusable residuals since future recovery chances fade.
    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    // Global waste pressure — scale leftover penalty by how close we
    // already are to the theoretical packing floor, tightening late-stream
    // compaction without disturbing early-stream behavior.
    if post_residual > 0 && progress > 0.4 {
        score += (post_residual as f64 / cap) * 6.0 * (progress - 0.4);
    }

    // Dual-fit lookahead — reward placements whose post-residual can
    // absorb the next item AND whose next-next remainder is small enough
    // to be plugged by any typical item (mean residual proxy).
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    // Fragmentation-aware tight-fit scaling — when few bins can fit
    // the item, amplify the value of the tightest placement so we don't
    // waste scarce capacity on loose fits.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 3.0 / fitting_bins_count as f64;
    }

    // NEW: residual entropy shaping — leftovers that decompose cleanly into
    // the next item's size plus a small, pluggable unit (1..=3) are near-perfect
    // seeds for future exact fills; reward that decomposition structure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 1 && rem2 <= 3 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // NEW: consolidation pressure — when many bins are open, mildly favor
    // placements that bring a bin's residual closer to (rather than further
    // from) zero, reducing the number of half-empty stragglers that must be
    // closed later.
    if open_bins_count > 8 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 4.0 * (open_bins_count as f64 / 20.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 260.0;
    }

    // Tiered dead-space penalty (steeper near zero).
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;

    // Continuous quadratic dead-space pressure.
    if post_residual > 0 {
        score += 0.045 * prf * prf / cap;
    }

    // Structured residual rewards (divisible leftovers are reusable).
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 40.0;
    }

    // Lookahead: exact / tight fit shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 8.0 + 6.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 18.0;
            }
            // Two-step lookahead: remainder absorbable by portfolio mean residual.
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 4.0 * (1.0 - rem2 as f64 / cap);
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        // Large item + fragmented portfolio: fresh bin is safer.
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        // Two-pack and three-pack lookahead on a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 30.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 20.0;
                }
            }
