    // the next item comfortably, discourage creating yet another mid-size
    // leftover that will never be consumed.
    if post_residual > 0 && next_item_size > 0 && mean_residual > next_item_size as f64 * 1.8 && open_bins_count > 8 {
        score += 4.0 * (mean_residual / cap).min(0.4);
    }

    score
}

