            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((post_residual as f64 + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Fresh-bin residual divisibility — a leftover that is an exact
        // multiple of the next item's size can absorb repeated copies of it,
        // making a fresh bin much safer to open.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // Avoid opening a bin whose post-residual is smaller than the
        // mean residual of the portfolio — existing slack would absorb the
        // item with less waste.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (post_residual as f64 / mean_residual).min(1.0));
        }
        // NEW: dual-fit lookahead — if the fresh bin's post-residual can host
        // the next item AND still leave room for a following small item
        // (proxied by mean residual), opening is safe; reward proportionally.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 as f64 >= mean_residual * 0.9 && rem2 > 0 {
                score -= 8.0 * (1.0 - progress) * (rem2 as f64 / cap);
            }
        }
        // NEW: large-item fresh-bin guard — opening a bin for a large item
        // whose post-residual is a dead zone (below mean residual but above
        // typical small-item band) wastes capacity; penalize harder late.
        if post_residual > 0 && post_residual as f64 > mean_residual && post_residual < 40 && item_size as f64 / cap > 0.4 {
            score += 9.0 + 8.0 * progress;
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((post_residual as f64 - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = post_residual as f64 / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - post_residual as f64 / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - post_residual as f64) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (post_residual as f64 / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection — a placement is bad if its post-residual
    // cannot be filled by the next item nor falls in the common small-item
    // band (<= mean residual proxy); apply a late-stream amplified penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure — when the post-residual is
    // within the pluggable band of the next item AND few bins fit, push
    // harder so scarce fits are consumed precisely.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // NEW: near-exact residual tightening — residuals within 2 units of a
    // multiple of the next item size indicate a future near-perfect fit;
    // reward mildly to steer compaction toward alignable leftovers.
    if next_item_size > 2 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual % next_item_size;
        if rem2 <= 2 {
            score -= 5.0 * (1.0 - progress);
        } else if next_item_size - rem2 <= 2 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 260.0;
    }

    // Tiered dead-space penalty (steeper near zero).
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;

    // Continuous quadratic dead-space pressure.
    if post_residual > 0 {
        score += 0.045 * prf * prf / cap;
    }

    // Structured residual rewards (divisible leftovers are reusable).
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 40.0;
    }

    // Lookahead: exact / tight fit shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 8.0 + 6.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 18.0;
            }
            // Two-step lookahead: remainder absorbable by portfolio mean residual.
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 4.0 * (1.0 - rem2 as f64 / cap);
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        // Two-pack and three-pack lookahead on a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 30.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 20.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 24.0 * (1.0 - progress);
            }
        }
        // Never strand a tiny residual from a fresh bin.
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Discourage fresh bin when portfolio slack suffices.
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        // Fresh-bin leftover pairability with portfolio mean.
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        // Fresh-bin residual absorbability by next item.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // NEW: fresh-bin residual divisibility — a leftover that is an exact
        // multiple of the next item's size can absorb repeated copies of it.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: avoid opening a bin whose post-residual is smaller than the
        // mean residual of the portfolio — existing slack would absorb the item.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (post_residual as f64 / mean_residual).min(1.0));
        }
        // NEW: fresh bin is safer when portfolio slack cannot host the next item.
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
    }

    // Mid-stream awkward band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += prf / cap * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }

    // Global waste pressure after early stream.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // NEW: dead-space trap detection — post-residual cannot be filled by the
    // next item nor falls in the common small-item band; amplified late.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // NEW: compaction pull toward exact closure when fits are scarce.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // NEW: residual/next-item mismatch penalty (from best heuristic).
    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // NEW: multi-copy absorption reward — residual that holds >=2 next items
    // is valuable, especially early/mid stream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let copies = post_residual / next_item_size;
        if copies >= 2 {
            score -= 5.0 * (1.0 - progress) * (copies.min(4) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Dead-space penalty: refined tiers with steeper wall near zero.
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * (post_residual as f64);
    // Continuous quadratic dead-space pressure for mid-range leftovers.
    let prf = post_residual as f64;
    if post_residual > 0 {
        score += 0.04 * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 40.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 14.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (post_residual as f64 / cap);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((post_residual as f64 + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Fresh-bin residual divisibility — a leftover that is an exact
        // multiple of the next item's size can absorb repeated copies of it.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // Avoid opening a bin whose post-residual is smaller than the mean
        // residual of the portfolio — existing slack would absorb the item.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (post_residual as f64 / mean_residual).min(1.0));
        }
        // NEW: fresh-bin lookahead chain — if the fresh bin's post-residual can
        // host the next item AND the remaining gap after that still exceeds
        // the mean residual, opening is safe (chain continues). Reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // NEW: penalize opening a fresh bin when the item could have gone
        // almost anywhere — high fitting_bins_count means plenty of slack.
        if fitting_bins_count >= 4 && item_size as f64 / cap < 0.4 {
            score += 7.0 * (1.0 - item_size as f64 / cap);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((post_residual as f64 - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = post_residual as f64 / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - post_residual as f64 / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - post_residual as f64) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (post_residual as f64 / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (post_residual as f64 / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection — a placement is bad if its post-residual
    // cannot be filled by the next item nor falls in the common small-item
    // band (<= mean residual proxy); apply a late-stream amplified penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure — when the post-residual is
    // within the pluggable band of the next item AND few bins fit, push
    // harder so scarce fits are consumed precisely.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // NEW: two-item lookahead closure — if the residual after placing the
    // next item can be exactly closed by the item after (approximated by
    // mean residual as a typical size), reward strongly; this drives
    // near-perfect packing in dense streams.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.0 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // NEW: variance-aware tightness — when residuals are highly fragmented
    // (high mean residual relative to capacity), push harder toward minimal
    // post-residuals to consolidate slack.
    let frag_index = mean_residual / cap;
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 260.0;
    }

    // Tiered dead-space penalty (steeper near zero).
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;

    // Continuous quadratic dead-space pressure.
    if post_residual > 0 {
        score += 0.04 * prf * prf / cap;
    }

    // Lookahead: exact / tight fit rewards, penalize gaps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            // Near-miss band: leftover just above next item keeps options open.
            if rem2 <= 4 {
                score -= 8.0 + 6.0 * (1.0 - progress);
            }
            // Chained-fit residuals.
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 18.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        // Two-pack and three-pack lookahead on a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 30.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 20.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 24.0 * (1.0 - progress);
            }
        }
        // Never strand a tiny residual from a fresh bin.
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        // Discourage fresh bin when portfolio slack suffices.
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        // Fresh-bin leftover pairability with portfolio mean.
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        // MUTATION: fresh-bin divisibility chain — leftover that is an exact
        // multiple of next item's size can absorb repeated copies.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // MUTATION: avoid opening a fresh bin whose post-residual is below
        // the portfolio's mean residual — existing slack would absorb it.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        // MUTATION: fresh-bin chain safety — if post-residual can host the
        // next item and the remaining gap still exceeds mean residual,
        // opening is safe (chain continues).
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // MUTATION: penalize fresh bin when many bins already fit the item.
        if fitting_bins_count >= 4 && item_size as f64 / cap < 0.4 {
            score += 7.0 * (1.0 - item_size as f64 / cap);
        }
    }

    // Mid-stream awkward band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += prf / cap * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Two-step lookahead — reward residuals that can absorb the next item
    // AND leave a remainder absorbable by portfolio mean residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    // Waste-ratio coupling — penalize leftovers that mismatch the next
    // item's size class, scaled by progress.
    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Global waste pressure — tighten late-stream compaction.
    if post_residual > 0 && progress > 0.4 {
        score += prf / cap * 6.0 * (progress - 0.4);
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += prf / cap * 3.0 / fitting_bins_count as f64;
    }

    // Structured residual reward for round-number leftovers.
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0) {
        score -= 12.0;
    }

    // MUTATION: dead-space trap detection — post-residual the next item
    // cannot use and that exceeds mean residual; amplified late-stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // MUTATION: compaction pull toward exact closure when fits are scarce.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // MUTATION: two-item lookahead closure — residual after the next item
    // closeable by a typical (mean-residual) size is rewarded.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 1 && rem2 as f64 <= mean_residual * 1.5 {
            score -= 3.0 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // MUTATION: variance-aware tightness — under high fragmentation push
    // harder toward minimal post-residuals.
    let frag_index = mean_residual / cap;
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // MUTATION: small unfillable band — residuals below next item and below
    // 25 get a decayed penalty to avoid stranding tiny gaps mid-stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let prf = post_residual as f64;

    // Dead-space penalty: refined tiers with steeper wall near zero.
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;
    // Continuous cubic dead-space pressure: steeper than parent's quadratic
    // for mid-range leftovers, which was the diagnosed weakness.
    if post_residual > 0 {
        score += 0.055 * prf * prf / cap + 0.9 * (prf / cap).powi(3) * cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 40.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 14.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (prf / cap);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 6.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_size as f64 / cap < 0.4 {
            score += 7.0 * (1.0 - item_size as f64 / cap);
        }
        // NEW: fresh-bin efficiency floor — only open a new bin if the item
        // fills it well; a large item leaving a large fresh residual is worse
        // than squeezing into a fragmented open bin.
        if prf > 0 && prf / cap > 0.55 && item_size as f64 / cap < 0.45 {
            score += 18.0 * (prf / cap - 0.55) * (1.0 + progress);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.0 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    let frag_index = mean_residual / cap;
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // NEW: dead-space ratio gate — penalize placements whose post-residual
    // exceeds both the next item and the mean slack, scaled by how many
    // alternative bins could also fit the item (more alternatives = more
    // freedom to avoid this dead-space trap).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += 3.5 * (1.0 - prf / next_item_size as f64) * (1.0 + 0.5 * (fitting_bins_count.min(6) as f64 - 1.0) / 5.0);
    }

    // NEW: residual-band resonance — reward leaving a post-residual that
    // matches common small-item sizes (multiples of 5 in the 5..=50 band),
    // which are likely to appear in unknown integer distributions.
    if post_residual > 0 && post_residual <= 50 && post_residual % 5 == 0 {
        score -= 4.0 * (1.0 - prf / 50.0) * (0.6 + 0.4 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 260.0;
    }

    // Tiered dead-space penalty (steeper near zero).
    let dead = if post_residual < 5 { 8.0 } else if post_residual < 10 { 5.5 } else if post_residual < 16 { 3.4 } else if post_residual < 20 { 2.5 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;

    // Continuous quadratic dead-space pressure.
    if post_residual > 0 {
        score += 0.045 * prf * prf / cap;
    }

    // Structured residual rewards (divisible leftovers are reusable).
    if post_residual > 0 && (post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0) {
        score -= 40.0;
    }

    // Lookahead: exact / tight fit shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 8.0 + 6.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 18.0;
            }
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 4.0 * (1.0 - rem2 as f64 / cap);
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }
    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let size_bias = (item_size as f64 / cap) * 34.0;
        score += 27.0 * waste_ratio - 14.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_size as f64 / cap > 0.7 {
            score -= 16.0;
        }
        if item_size as f64 / cap > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 30.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 20.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 24.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Divisible fresh-bin leftover can absorb repeated next items.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        // Avoid opening a bin whose post-residual is below portfolio slack.
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        // Chain lookahead: fresh bin's post-residual can host next item and
        // the remaining gap still exceeds mean residual — opening is safe.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 6.0 * (1.0 - progress);
            }
        }
        // Penalize fresh bin when item could fit almost anywhere.
        if fitting_bins_count >= 4 && item_size as f64 / cap < 0.4 {
            score += 7.0 * (1.0 - item_size as f64 / cap);
        }
    }

    // Mid-stream awkward band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += prf / cap * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }

    // Global waste pressure after early stream.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // Dead-space trap: residual neither fillable by next item nor in the
    // common small-item band — amplified late-stream penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure when fits are scarce.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure via mean-residual proxy.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.0 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness: consolidate slack when highly fragmented.
    let frag_index = mean_residual / cap;
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Mismatch penalty: leftover that cannot pair with the next item.
    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Residual after next item: reward large reusable remainder, penalize tiny.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    score
}

