    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - post_residual as f64 / cap);
