        // NEW: fresh-bin triadic closure — if item + next + a typical small
        // item (mean_residual proxy) fills the bin almost exactly, opening
        // is a strong plan; reward proportionally.
        if next_item_size > 0 {
            let tri_gap = cap - item_size as f64 - next_item_size as f64;
            if tri_gap >= 0.0 && tri_gap <= mean_residual * 1.2 {
