            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 7.0 * structure;
            if rem2 > 0 && rem2 < 10 {
