        let rem2 = post_residual - next_item_size;
        if rem2 >= next_item_size && (rem2 - next_item_size) < 6 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // NEW: late-stream bin-count pressure — near the end, opening extra bins
    // is almost pure waste; make the fresh-bin option costlier.
    if bin_residual == bin_capacity && progress > 0.6 && open_bins_count > 3 {
        score += 18.0 * (progress - 0.6) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
