    // new ultra-tight tier, pushing hard for near-exact closures.
    let dead = if post_residual < 3 { 11.0 } else if post_residual < 6 { 8.4 } else if post_residual < 10 { 6.0 } else if post_residual < 14 { 4.2 } else if post_residual < 18 { 3.0 } else if post_residual < 24 { 2.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf;
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 270.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
