        // Fresh-bin economy — opening a bin is only worth it when the
        // leftover it strands is smaller than the average stranded slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
