        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        if next_item_size > 0 && (item_size as u64 + 2 * next_item_size as u64) == bin_capacity as u64 {
