    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
