    // the more valuable it is to leave a usable (>= next item or near-zero)
    // leftover rather than a stranded mid-gap one.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // NEW: late-stream compaction surge — in the final quarter, any nonzero
    // leftover on an existing bin is a near-loss; tighten the squeeze so the
    // last items close bins exactly instead of stranding slack.
    if progress > 0.85 && post_residual > 0 {
        score += (prf / cap) * 10.0 * (progress - 0.85) * 6.0;
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 8.0 * (progress - 0.85) * 6.0;
        }
    }

    // NEW: dual-fit harmony — when multiple bins fit, prefer the one whose
    // post-residual best matches the *mean* residual (keeps future closure
    // options open), scaled by how many alternatives exist.
    if post_residual > 0 && fitting_bins_count >= 3 {
        let harmony = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 3.0 * harmony * (fitting_bins_count.min(8) as f64 / 8.0);
    }

    score
}

