        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // NEW: late-stream compaction squeeze — near the end, every unit of
    // leftover in an open bin is potential dead space; push harder toward
    // zero-residual placements and penalize mid-range leftovers.
    if progress > 0.6 && post_residual > 0 {
        let squeeze = (progress - 0.6) / 0.4;
        score += (prf / cap) * 10.0 * squeeze;
        if prf < 5.0 {
            score -= 8.0 * squeeze;
        }
    }

    // NEW: fill-ratio gradient — reward bins that end up mostly full,
    // proportional to how full the bin becomes after placement.
    if post_residual > 0 {
        let fill = 1.0 - prf / cap;
        score -= 3.0 * fill * fill * (0.5 + 0.5 * frag_index.min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
