    let dead = if post_residual < 3 { 10.0 } else if post_residual < 5 { 8.2 } else if post_residual < 8 { 6.5 } else if post_residual < 12 { 5.0 } else if post_residual < 16 { 3.5 } else if post_residual < 22 { 2.5 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
