    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    // MUTATION: tier boundaries tuned tighter near zero; late-stream multiplier
    // now ramps quadratically so residual hoarding is punished harder as the
    // stream drains.
    let dead = if post_residual < 2 { 11.2 } else if post_residual < 4 { 8.6 } else if post_residual < 6 { 7.1 } else if post_residual < 9 { 5.6 } else if post_residual < 13 { 4.2 } else if post_residual < 18 { 3.0 } else if post_residual < 25 { 1.8 } else if post_residual < 36 { 0.9 } else if post_residual < 50 { 0.4 } else { 0.0 };
    let late_ramp = 1.0 + 0.5 * progress + 0.5 * progress * progress;
