            let over_mean = (prf - mean_residual).max(0.0) / cap;
            score += 16.0 * over_mean * (0.6 + 0.4 * progress);
        }
        // NEW: next-item divisibility shaping — a fresh-bin leftover that is a
        // whole multiple of the next item will drain cleanly; reward it, with
        // the reward decaying as the stream progresses (chain value matters
        // most early/mid stream).
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
            let mult = post_residual / next_item_size;
