    // nonzero leftover on an existing bin should be strongly penalized so
    // remaining items drain residual space instead of opening fresh bins.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: harvest-window alignment — reward bins whose post-residual lands
    // within a narrow window just above the mean residual, since such
    // leftovers match the typical remaining item class and get drained
    // quickly rather than stranded.
    if post_residual > 0 && mean_residual > 1.0 && progress < 0.85 {
        let window = (prf - mean_residual) / mean_residual.max(1.0);
        if window >= 0.0 && window <= 0.25 {
            score -= 3.5 * (1.0 - window / 0.25) * (1.0 - progress);
        }
    }

    score
}

