    // Dead-space tiers: slightly sharpened mid-band to drain awkward leftovers.
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.2 } else if post_residual < 8 { 6.6 } else if post_residual < 12 { 5.1 } else if post_residual < 16 { 3.6 } else if post_residual < 22 { 2.5 } else if post_residual < 30 { 1.3 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

