    // this pull proportionally to how few bins remain usable, since
    // perfect closures are the cheapest way to cut dead space.
    if next_item_size > 0 && next_item_size == bin_residual && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 / fitting_bins_count.max(1) as f64;
    }

    // NEW: dead-space budget sweep — leftovers slightly above the next item
