    }

    // NEW: residual-band coherence — favor leftovers that keep the bin's
    // remaining space within one next-item of the stream's typical slack,
    // reducing variance of stranded dead space across bins.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let band = ((prf - next_item_size as f64) % next_item_size.max(1) as f64) / next_item_size.max(1) as f64;
        score += 2.0 * band * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item are pure waste.
    if post_residual < 10 {
        score += 1000.0;
    }
    // Small gaps that likely cannot fit typical items (below 20) are near-dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    }

    // Reward tight fits: the smaller the relative post_residual, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual < 10 {
            score += 900.0; // still avoid creating dead space
        }
    }

    // Open-bin pressure: discourage proliferation of bins; favor consolidating into
    // already-open bins, but only if the fit is acceptable.
    if bin_residual != bin_capacity {
        score -= 25.0 + 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize so it is chosen only when fits are bad.
        score += 120.0 + 5.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin is below-average fullness, prefer filling it
    // to balance residuals across open bins.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slightly prefer leaving larger residuals.
        score += 0.1 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Early in the stream, be a bit more willing to open bins (build diversity);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 80.0 * (1.0 - progress);
    } else {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
