    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (min size 1,
    // but small residuals under ~10 are likely unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward if the next item can fit in the post_residual,
    // penalize if next item is large and would leave this bin stranded.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; residual quality matters less
            score += 5.0;
        }
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Time horizon: early in the stream, be more conservative about filling bins
    // tightly (keep flexibility); later, squeeze harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Compare against mean residual: placing into a bin with residual far below
    // mean (a small leftover bin) is good; using a large-residual bin on a small
    // item wastes capacity.
    let res = bin_residual as f64;
    if res > mean_residual + 20.0 && item_size < 30 {
        score += 12.0;
    } else if res < mean_residual - 10.0 {
        score -= 8.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to typical residual or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual + 30.0;
        if large_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // discourage opening new bins when existing ones suffice
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

