        // NEW: tight-window conservation — when the item barely fits an open
        // bin (residual within 15% of item), make reuse nearly mandatory.
        if bin_residual < bin_capacity {
            let tight_margin = bin_residual as f64 - item_size as f64;
            if tight_margin >= 0.0 && tight_margin <= item_size as f64 * 0.15 {
