    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: dual-item sweep — when the current residual can host the next item
    // AND the item after that (approximated by mean residual), reward bins
    // that will be fully drained across two future steps.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 >= mean_residual * 0.5 && (rem2 as f64 - mean_residual).abs() <= 4.0 {
            score -= 5.5 * (1.0 - 0.3 * progress);
        }
    }

    // NEW: fragmentation drain — when many bins are open and mean residual is
    // high, penalize leaving large leftovers on existing bins to force
    // consolidation into fewer bins.
    if post_residual > 0 && open_bins_count > 12 && frag_index > 0.35 {
        score += 3.5 * frag_index * (prf / cap) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post-residual: strong lookahead reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item would not fit: penalize proportional dead space.
        score += 10.0 + 0.25 * (next_item_size.saturating_sub(post_residual)) as f64;
    }

    // Penalize post-residual below the smallest plausible item (dead space), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + 30.0 * progress;
    }

    // Compare against mean residual: bins tighter than average are preferred targets.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && post_residual >= 0;
        if decent_fit_exists {
            score += 20.0 + 0.5 * item_size as f64;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // roomy bin good for upcoming big items
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.05 * post_residual as f64;

    score
}

