    // host the item, prefer the one whose leftover after placement is either
    // zero or the largest (most reusable); penalize the awkward middle band
    // where the leftover is neither closed nor broadly usable.
    if post_residual > 0 && bin_residual < bin_capacity {
        let usable = prf >= next_item_size as f64;
        let mid_band = prf > 8.0 && prf < 24.0 && !usable;
        if mid_band {
            score += 3.5 * (1.0 - prf / 24.0) * (0.6 + 0.4 * progress);
        }
        if usable && prf >= mean_residual {
            score -= 2.0 * ((prf - mean_residual) / cap).min(0.3);
        }
    }

    // MUTATION: open-bin count pressure — when the fleet of open bins grows
    // relative to remaining items, opening fresh bins should get costlier so
    // fill concentrates into existing residual space.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)).max(1) as f64;
        let spread = open_bins_count as f64 / remaining;
        if spread > 0.25 {
            score += 10.0 * (spread - 0.25).min(0.5);
        }
        if next_item_size > 0 && item_frac > 0.6 && prf < next_item_size as f64 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // MUTATION (gen 31): fine-grained residual fitting + lookahead coupling —
    // among existing bins, strongly prefer the one whose post-residual
    // exactly matches the next item OR leaves a leftover that itself matches
    // a fine-grained reusable window (<= 4 units of the mean residual).
    if bin_residual < bin_capacity && next_item_size > 0 && post_residual > 0 {
        let rem2 = post_residual as i64 - next_item_size as i64;
        if rem2 == 0 {
            score -= 10.0 * (1.0 - 0.5 * progress);
        } else if rem2 > 0 && (rem2 as f64) <= (mean_residual * 0.35).max(4.0) {
            score -= 7.0 * (1.0 - rem2 as f64 / (mean_residual * 0.35).max(4.0)) * (0.6 + 0.4 * progress);
        }
    }

    // MUTATION (gen 31): dead-space ratio compaction — penalize placements
    // that strand a leftover which neither the next item nor the average
    // item can ever absorb, scaled by how much of the bin stays empty.
    if post_residual > 0 && bin_residual < bin_capacity {
        let unusable = next_item_size == 0 || post_residual < next_item_size;
        if unusable && prf < mean_residual {
            score += 8.0 * (prf / cap) * (1.0 - 0.3 * progress);
        }
    }

    // MUTATION (gen 31): lookahead-driven new-bin veto — when a fresh bin
    // would strand a leftover the next item cannot use while some open bin
    // leaves a chain-usable leftover, make the fresh bin clearly worse.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, with accelerating (quadratic/cubic) waste penalty.
    let mut score = pr + (pr * pr) / cap + (pr * pr * pr) / (cap * cap);

    // Smooth tight-fit reward: strongly favor small post_residual via exp coupling.
    score -= 12.0 * (-(pr / cap) * 6.0).exp();

    // Stream-progress coupling: later in the stream, waste is more costly (smooth ramp).
    score += progress * (pr * pr) / cap * 1.5;

    // Lookahead: reward bins whose post_residual can still fit the next item,
    // with a smooth sigmoid-like term on how snugly it fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_quality = (pr - nx) / cap; // positive if next item fits
        score -= 4.0 * (fit_quality * 8.0).tanh();
    }

    // Last-chance bonus: if this is the only bin that can fit, prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * it;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() * 0.02;

    // New-bin candidate: empty bin should only win when the fit is genuinely poor
    // elsewhere; add a moderate opening cost scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Refined dead-space tiers with steeper wall near zero + quadratic pressure.
    let dead = if post_residual < 4 { 9.6 } else if post_residual < 8 { 6.6 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Lookahead shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 240.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 7.0 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 10.0 + 7.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 20.0;
            }
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 5.0 * (1.0 - rem2 as f64 / cap);
            }
            if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
                score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.5 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Tight-bin preference.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.8 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 18.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 9.0;
        }
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 34.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 22.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 26.0 * (1.0 - progress);
            }
            if item_size as u64 + 3 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
            {
                score -= 18.0 * (1.0 - 0.4 * progress);
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
            if pair_gap <= 6.0 {
                score -= 11.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 4.5 * overshoot * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        // Fresh-bin economy: penalize bins stranding worse-than-average slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream chain-friendly leftovers.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Scarcity-adjusted opening.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Big-item fresh-bin preference.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 28.0 * (item_frac - 0.45) * (1.0 - progress);
        }
    }

    // Mid-band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }

    // Global waste pressure.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 6.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Squander guard: strand-mismatch penalty scaled by fragmentation.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / next_item_size as f64).min(1.0));
    }

    // Residual-pool absorption check.
    if post_residual > 0 && open_bins_count > 6 && prf < mean_residual * 0.5 {
        score += 4.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
        if rem2 > 0 && rem2 <= 4 {
            score -= 8.0 + 6.0 * (1.0 - progress);
        }
    }

    // Next-item mismatch penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
        if post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if post_residual < next_item_size {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.5 && prf > 4.0 {
        score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 80.0 * (prf / cap) * (progress - 0.85);
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 180.0 * (progress - 0.85);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by capacity fractions
    // are "usable" classes (can host future standard-size items), others are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual divisible by 10 -> highly reusable residual class.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Class 2: divisible by 5 but not 10 -> moderately reusable.
    else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Class 3: tiny residual (< 10) -> dead space penalty, worse the smaller it is.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Integer-division thresholds on post_residual: quarter classes of capacity.
    let quarter = (bin_capacity / 4) as f64;
    if pr <= quarter {
        score += quarter - pr; // near-empty bin after placement: cramped
    } else if pr >= 2.0 * quarter && pr <= 3.0 * quarter {
        score -= 4.0; // sweet spot: half-full bin
    }

    // Coupling with next item: reward residual classes that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact-class match: residual equals next size (perfect chaining).
            if post_residual == next_item_size {
                score -= 12.0;
            } else if post_residual - next_item_size < 10 {
                score -= 6.0; // leaves near-zero dead space after next item
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close we were.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5; // prefer tighter competition
    }

    // New-bin candidate: only attractive when residual classes of open bins are bad.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let class_badness = (mean_residual % 10.0) / 10.0; // harmonic misalignment of mean residual
        score = cap * (0.55 + 0.3 * class_badness) + open * 2.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 25.0; // never open a new bin when this is the only fitting option
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big lookahead item: fresh bin is valuable
        }
    }

    // Mild diversity bonus: bins whose residual is in a different harmonic class
    // than the current item keep class separation clean.
    if bin_residual % 10 != item_size % 10 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: refined tiers with a sharper cliff below 6 units,
    // since sub-6 leftovers are almost never reusable mid-stream.
    let dead = if post_residual < 2 { 11.5 } else if post_residual < 4 { 9.6 } else if post_residual < 6 { 7.6 } else if post_residual < 8 { 6.4 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 270.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (prf / cap);
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        if next_item_size > 0 && (item_size as u64 + 2 * next_item_size as u64) == bin_capacity as u64 {
            score -= 26.0 * (1.0 - 0.5 * progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.6 {
            score += 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf >= mean_residual {
            score -= 4.0 * (1.0 - progress) * (prf / cap).min(0.4);
        }
        // Fresh-bin economy: opening a bin is only worth it when the leftover
        // it strands is smaller than the average stranded slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream consolidation: prefer chain-friendly post-residuals.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Scarcity-adjusted opening.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Pair-completion opening.
        if post_residual > 0 && (prf + mean_residual - cap).abs() <= 6.0 {
            score -= 11.0;
        }
        // Triple-chain opening.
        if next_item_size > 0
            && (item_size as u64 + 3 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
        {
            score -= 18.0 * (1.0 - 0.4 * progress);
        }
        // Stranded-leftover guard.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        // Residual-floor opening: prefer post-residuals just above the next
        // item; penalize wide overshoots more sharply late in the stream.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 5.5 * overshoot * (0.4 + 0.6 * progress);
        }
        // Big-item fresh-bin preference.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 7.0 * (item_frac - 0.45) * 4.0 * (1.0 - progress);
        }
        // NEW: open-bin slack drain — when the aggregate residual across open
        // bins already exceeds the item, opening a fresh bin is wasteful;
        // scale the penalty by how comfortably the existing pool absorbs it.
        let pool_slack = mean_residual * open_bins_count as f64;
        if item_size as f64 <= pool_slack * 0.9 {
            score += 6.0 * (1.0 - (item_size as f64 / pool_slack)) * (0.5 + 0.5 * progress);
        }
        // NEW: near-exact fresh-bin fill — if the fresh bin's leftover is
        // within a hair of the next item, opening is nearly free.
        if post_residual > 0 && next_item_size > 0 {
            let d = (prf - next_item_size as f64).abs();
            if d <= 3.0 {
                score -= 14.0 * (1.0 - d / 4.0) * (1.0 - 0.5 * progress);
            }
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive, extended earlier (from 0.82) and with a
    // broader exact-closure window (rem2 < 5) to drain residual space harder.
    if progress > 0.82 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.5 * (prf / cap) * (progress - 0.82) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 9.0 * (progress - 0.82) * 20.0;
        }
    }

    // NEW: dead-space floor sweep — leftovers in the awkward 6..16 band that
    // neither match the next item nor any multiple of it are the primary
    // source of wasted space; penalize proportionally to stream progress.
    if post_residual >= 6 && post_residual < 16 && next_item_size > 0 {
        let usable = post_residual % next_item_size == 0
            || next_item_size >= post_residual && post_residual >= 4 && next_item_size - post_residual <= 2;
        if !usable {
            score += 3.5 * (1.0 - (post_residual as f64 - 5.0) / 11.0) * (0.3 + 0.7 * progress);
        }
    }

    // NEW: fit-quality gradient — among fitting bins, reward those whose
    // post-residual stays closest to the mean residual (keeps the residual
    // distribution compact and future items' fit predictability high).
    if post_residual > 0 && bin_residual < bin_capacity {
        let dev = ((prf - mean_residual) / cap).abs();
        score += 1.8 * dev * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.0 } else if post_residual < 8 { 6.4 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 270.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (prf / cap);
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
