    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: aggregate dead-space drain — when the stream's mean residual is low
    // (bins are nearly full), push harder toward zero-leftover placements on
    // existing bins so residual variance collapses instead of accumulating.
    if post_residual > 0 && frag_index < 0.25 && open_bins_count > 6 {
        score += 3.5 * (0.25 - frag_index) * 4.0 * (prf / cap) * (0.5 + progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0 * (1.0 - frag_index * 4.0);
        }
    }

    // NEW: two-item residual stacking — reward placements whose leftover can
    // host the next item AND still leave a slot matching the mean residual,
    // chaining toward a near-zero terminal leftover.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if (rem2 as f64 - mean_residual).abs() <= 3.0 {
            score -= 4.5 * (1.0 - ((rem2 as f64 - mean_residual) / 4.0).abs()) * (0.6 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Core tightness preference: strongly reward small post-residual
    score -= (cap - post) / cap * 40.0;

    // Penalize dead space that is too small to ever be useful
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0;
        }
        // If this bin is the only one fitting the current item, prioritize strongly
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // discourage opening new bins early / when many bins open
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but encourage when item leaves awkward residue in any open bin
        if fitting_bins_count > 0 && post > 0.0 && post < 15.0 {
            score -= 10.0;
        }
    } else {
        // Last-chance bonus for existing bins
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post) * 0.5;

    // Prefer bins below mean residual (compact usage)
    score += (mean_residual - post) * 0.15;

    score
}

