        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: dead-space budget coupling — when the item nearly empties a bin
    // (tiny post-residual) while many bins remain open, reward extra so
    // near-full bins are drained rather than left as scattered dead space.
    if post_residual > 0 && post_residual <= 4 && open_bins_count > 5 {
        score -= 4.0 * (1.0 - prf / 5.0) * (1.0 + 0.5 * progress);
    }

    // NEW: two-step sum closure — reward bins whose leftover equals the sum
    // of the next item plus a small tail, enabling two-item exact drainage.
    if next_item_size > 1 && post_residual > next_item_size {
        let tail = post_residual - next_item_size;
        if tail >= 1 && tail <= 6 {
            score -= 7.0 * (1.0 - tail as f64 / 7.0) * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = (mean_residual / cap).clamp(0.0, 1.0);

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 270.0;
    }

    // Finer-grained dead-space tiers near zero, progress-amplified.
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.0 } else if post_residual < 8 { 6.4 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);

    // Continuous quadratic dead-space pressure, fragmentation-scaled.
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Lookahead: exact / tight fit rewards, penalize gaps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 220.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 16.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
