    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.5 && prf > 4.0 {
        score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // NEW: two-item chain closure — leftover that the next item drains to a
    // portfolio-absorbable remainder is nearly free.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 1 && rem2 as f64 <= mean_residual * 1.5 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
        if rem2 % next_item_size.max(1) == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // NEW: variance-aware tightness — under high fragmentation, keep
    // residuals small to preserve future fit options.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // NEW: small stranded leftover under many open bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 && open_bins_count > 4 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // later in the stream, dead space matters more -> convex penalty grows
    let dead_penalty = (x * x) * (100.0 + 300.0 * progress * progress);
    score += dead_penalty;

    // Reward moderately full bins smoothly (quartic bump around x ~ 0.1-0.3)
    let tightness = ((x - 0.15) * (x - 0.15)).sqrt();
    score -= 40.0 * (-50.0 * tightness).exp() * (0.5 + progress);

    // Penalize leaving space that next item could use poorly:
    // if next item fits exactly-ish, reward; if post residual is just slightly
    // below next_item_size, penalize (unusable sliver)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let usable = if pr >= ni { 1.0 } else { 0.0 };
        // smooth: residual close to next item size is great
        score -= 25.0 * (-gap / 30.0).exp();
        // sliver penalty: pr < ni but close to ni -> wasted
        let sliver = (ni - pr).max(0.0) as f64;
        score += 15.0 * (-sliver / 8.0).exp() * (1.0 - usable.max(0.0).min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // mild competition penalty scaled by number of alternatives
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual early (keep big bins for big items),
    // smooth interaction with progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (30.0 - 20.0 * progress);

    // New-bin candidate: make it unattractive unless post_residual is large
    // (i.e., item is small) and stream is early; smooth sigmoid gate
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let gate = 1.0 / (1.0 + (-(x - 0.5) * 8.0).exp());
    score += is_new_bin * (60.0 * gate + 40.0 * (1.0 - progress));

    // Slight preference to consolidate: fewer open bins favored for tight fits
    score += 0.5 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
