        // mean residual cannot host them should open fresh bins cheaply.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 7.0 * (item_frac - 0.45) * 4.0 * (1.0 - progress);
        }
        // NEW: exact-closure fresh-bin preference — when the fresh bin's
        // post-residual equals the mean residual (a known chainable size),
        // opening is nearly free since the slack class is already established.
