    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty — the fewer bins can host the
    // item, the more valuable it is to leave a *usable* leftover.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty — leftovers in the awkward band just
    // below half the mean residual are rarely reusable; penalize them
    // proportionally to stream progress.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation — bins already near full should absorb the
    // item if the resulting leftover remains chain-usable; this compacts
    // nearly-full bins instead of scattering fill across many bins.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // exact-fill sweep refinement — when the post-residual matches a
    // small multiple of the next item, close the bin aggressively.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // late-stream zero-waste drive — near the end of the stream, any
    // nonzero leftover on an existing bin should be strongly penalized so
    // remaining items drain residual space instead of opening fresh bins.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: residual-class consolidation — bins whose post-residual lands
    // within a narrow band of the mean residual keep the slack population
    // homogeneous, which lets later items close many bins with one size
    // class instead of scattering across incompatible leftovers.
    if post_residual > 0 && (prf - mean_residual).abs() <= 3.0 && open_bins_count > 3 {
        score -= 4.0 * (1.0 - 0.4 * progress);
    }

    // NEW: near-closure drain bonus — bins whose residual before placement
    // is within a few units of the item should be drained even if the
    // leftover is not perfectly structured; every unit of dead space
    // avoided on a nearly-full bin is a direct bin saved.
    if bin_residual >= item_size && bin_residual - item_size <= 4 && bin_residual < bin_capacity {
        score -= 5.0 + 3.0 * (1.0 - (bin_residual - item_size) as f64 / 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10, the minimum item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // heavily penalize creating a dead gap
    }
    // Gaps that only fit very small items (10..20) are semi-dead.
    else if post_residual < 20 && post_residual > 0 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // --- Open-bins pressure ---
    // Prefer already-open bins when many bins are open; discourage sprawl.
    score += open_bins_count as f64 * 1.5;

    // --- Last-chance bin ---
    // If this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine if the item is large (poor fit anywhere),
        // or if existing bins are mostly full (low mean residual).
        let mean_res = mean_residual;
        if item_size >= 60 || mean_res < 20.0 {
            score -= 30.0;
        } else {
            // Otherwise opening a new bin wastes residual capacity of open bins.
            score += 15.0 + mean_res;
        }
    }

    // --- Lookahead (k=2) coupling ---
    if next_item_size > 0 {
        // If the next item fits exactly in the post residual, this placement sets up a chain.
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits: modest reward proportional to how snugly.
            score -= (next_item_size as f64) * 0.3;
        } else {
            // Next item won't fit here: penalize leaving a gap that nothing can use.
            let gap_waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
            if post_residual > 0 && next_item_size > post_residual && post_residual < 30 {
                score += 10.0;
            }
            let _ = gap_waste;
        }
    }

    // Slight preference for fuller bins (lower post residual already does this,
    // but add a mild non-linear nudge toward tight packing).
    score += (post_residual as f64).powi(2) * 0.005;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    let dead = if post_residual < 3 { 10.8 } else if post_residual < 5 { 8.2 } else if post_residual < 8 { 6.6 } else if post_residual < 12 { 5.1 } else if post_residual < 16 { 3.5 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 280.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
