    // item AND leave a slot near the mean residual, chaining toward zero.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if (rem2 as f64 - mean_residual).abs() <= 3.0 {
            score -= 4.5 * (1.0 - ((rem2 as f64 - mean_residual) / 4.0).abs()) * (0.6 + 0.6 * progress);
        }
    }

    // NEW: scarcity-aware chain compaction — when many bins fit the item,
    // prefer the bin whose placement leaves the tightest chainable remnant;
    // this reduces the scattered dead-space that inflates total bins.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count >= 3 {
        let rem2 = post_residual - next_item_size;
        if rem2 < 5 {
            score -= (3.0 + 1.5 * (1.0 - rem2 as f64 / 5.0)) * (0.7 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual is already the base signal).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // Sweet spot: leftover that can still host small items.
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when the item
    // fits poorly in every open bin or open bins are already congested.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Baseline neutral score for a fresh bin.
        score = bin_capacity as f64 - item_size as f64;
        // Prefer new bin when existing fits are bad (high mean residual dispersion proxy)
        // or when the item is large relative to typical residual.
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap < 0.0 || fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Slight penalty for spreading across many open bins when residuals are large.
        if (bin_residual as f64) > mean_residual + 20.0 {
            score -= 5.0;
        } else if (bin_residual as f64) < mean_residual - 20.0 {
            score += 5.0;
        }
    }

    score
}

