            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let unusable = (post_residual < 10) || (post_residual >= 10 && next_item_size > post_residual && next_item_size > 0);
        if unusable {
            score += (bin_capacity as f64) * 1.5; // heavy penalty for creating dead space
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Reward matching the next item into this bin's leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }

    // Open-bin pressure: penalize adding to bins when many are open,
    // encouraging consolidation rather than spreading.
    score += 0.3 * open_bins_count as f64;

    // Mild trend pressure: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below average (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

