    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty — the fewer bins can host the
    // item, the more valuable it is to leave a *usable* leftover.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty — leftovers in the awkward band just
    // below half the mean residual are rarely reusable; penalize them
    // proportionally to stream progress.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation — bins already near full should absorb the
    // item if the resulting leftover remains chain-usable; this compacts
    // nearly-full bins instead of scattering fill across many bins.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement — when the post-residual matches a
    // small multiple of the next item, close the bin aggressively.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive — near the end of the stream, any
    // nonzero leftover on an existing bin should be strongly penalized so
    // remaining items drain residual space instead of opening fresh bins.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // NEW: dual-drain lookahead — when the current leftover AND the mean
    // slack across open bins can jointly absorb the next two items, reward
    // draining this bin now so the aggregate dead space collapses.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if next_item_size as f64 <= mean_residual && rem2 as f64 >= next_item_size as f64 {
            let drain_depth = rem2 as f64 / next_item_size as f64;
            if drain_depth >= 2.0 {
                score -= 5.5 * (drain_depth.min(4.0) - 1.0) * (1.0 - 0.3 * progress);
            }
        }
    }

    // NEW: bin-count pressure coupling — when open bins already exceed the
    // theoretical density implied by mean residual, make reuse cheaper and
    // fresh openings costlier, tightening overall compaction.
    if open_bins_count > 6 && post_residual > 0 {
        let density_gap = (open_bins_count as f64 - (total_items.max(1) as f64 * cap / (cap + mean_residual))) / open_bins_count.max(1) as f64;
        if density_gap > 0.0 {
            score += 3.0 * density_gap.min(1.0) * (prf / cap);
            if bin_residual == bin_capacity {
                score += 8.0 * density_gap.min(1.0);
            }
        }
    }

    // NEW: harmonic leftover targeting — leftovers that can be exactly
    // partitioned by the next item into 2 or 3 equal parts are prime
    // closure candidates; reward proportionally to stream progress.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let r = post_residual % next_item_size;
        if r == 0 && (q == 2 || q == 3) {
            score -= 7.0 * (1.0 - 0.5 * progress) * (1.0 + 0.5 * frag_index);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - exact / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit in this bin's residual: penalize proportionally
        score += 10.0 + (next_item_size - post_residual) as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for opening new bins early when stream is young and bins are many
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
