        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive. MUTATION: trigger earlier (0.8) and
    // scale the drain reward by fragmentation so fragmented streams drain
    // residual space sooner.
    if progress > 0.8 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.8) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.8) * 20.0;
        }
        if frag_index > 0.4 && post_residual >= next_item_size {
            score -= 5.0 * frag_index * (progress - 0.8) * 10.0;
        }
    }

    // NEW MUTATION: mid-stream drain incentive — once past a third of the
    // stream, mildly reward bins whose leftover can absorb the next item
    // with small remainder, accelerating compaction before the endgame.
    if progress > 0.33 && progress <= 0.8 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 6 {
            score -= 3.0 * (1.0 - rem2 as f64 / 6.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, waste matters more (fewer chances to recover).
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    score += 12.0 * progress;

    // Reward tight fits (small post_residual), but penalize unusable slivers.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 40.0; // perfect fit is ideal
    } else if pr < 10.0 {
        // dead space: too small for the smallest item (1..100 range, but typical min ~10)
        score += 6.0 + pr * 0.5;
    }

    // Lookahead: if next item fits into post_residual, this bin stays productive.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 15.0 + 10.0 * progress;
            // extra reward when next item nearly fills the remainder
            let leftover = post_residual as f64 - next_item_size as f64;
            if leftover < 10.0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use the remainder: remainder likely becomes waste
            score += 5.0 * progress;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals below the mean (consolidate fullness),
    // keep roomy bins available for larger future items.
    if bin_residual as f64 > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // New empty bin candidate: only attractive when no open bin is decent.
    if bin_residual == bin_capacity {
        // base penalty so existing bins usually win...
        score += 18.0;
        // ...but if the item is large relative to capacity, opening fresh is fine
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // and if many bins are already open, adding one more is cheap
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild preference for filling bins that are already mostly full.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
