    else if post_residual >= 10 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits: the closer the fill to capacity, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate handling: only attractive when existing bins would
    // create dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by how badly current
        // bins would fit (dead-space risk of this placement).
        let dead_risk = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 20.0 + 15.0 * progress;
        if dead_risk > 0.0 {
            score -= 25.0; // opening a fresh bin beats making dead space
        }
        // Lookahead: if next item is small, a fresh bin with large residual
        // is valuable.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 8.0;
        }
    } else {
        // Existing-bin lookahead: if the next item fits exactly in the
