        }
        // Dead-space budget gate: only open a fresh bin if the leftover it
        // strands is below the mean residual scaled by fragmentation.
        if post_residual > 0 && open_bins_count > 4 {
            let budget = mean_residual * (0.6 + 0.8 * frag_index);
            if prf > budget {
                score += 6.5 * ((prf - budget) / cap).min(0.6) * (0.6 + 0.8 * progress);
            } else if prf <= budget * 0.5 {
                score -= 5.0 * (1.0 - prf / (budget * 0.5 + 1.0));
            }
        }
        // Harvestable-window alignment: cheap to open when the leftover lands
        // within a narrow window just above the next item.
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let window = post_residual - next_item_size;
            if window <= 6 {
                score -= 5.5 * (1.0 - window as f64 / 7.0) * (1.0 - 0.3 * progress);
            }
        }
        // NEW: fresh-bin scarcity override — when very few bins can host the
        // item and the mean residual cannot absorb it, opening is nearly free.
        if next_item_size > 0 && fitting_bins_count <= 1 && item_size as f64 > mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation: compact nearly-full bins when the leftover
    // remains chain-usable instead of scattering fill across bins.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement: drain bins that can be finished cleanly
    // with small multiples of the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive: near the end, any nonzero leftover on an
    // existing bin is penalized so remaining items drain residual space.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // Aggregate dead-space drain: when the stream's mean residual is low,
    // push harder toward zero-leftover placements on existing bins.
    if post_residual > 0 && frag_index < 0.25 && open_bins_count > 6 {
        score += 3.5 * (0.25 - frag_index) * 4.0 * (prf / cap) * (0.5 + progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0 * (1.0 - frag_index * 4.0);
        }
    }

    // Two-item residual stacking: reward placements whose leftover can host
    // the next item AND still leave a slot matching the mean residual.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if (rem2 as f64 - mean_residual).abs() <= 3.0 {
            score -= 4.5 * (1.0 - ((rem2 as f64 - mean_residual) / 4.0).abs()) * (0.6 + 0.6 * progress);
        }
    }

    // NEW: compaction-vs-lookahead blend — when the residual can host the next
    // item exactly, deepen the reward as fragmentation rises, coupling fine
    // residual fitting with lookahead anticipation.
    if next_item_size > 0 && post_residual > 0 && post_residual == next_item_size {
        score -= 3.0 + 4.0 * frag_index;
    }

    // NEW: mid-stream tight-bin pull — bins whose residual is just above the
    // item size should absorb it to keep leftover variance low.
    if post_residual > 0 && bin_residual as f64 >= item_size as f64
        && (bin_residual as f64 - item_size as f64) <= 4.0
        && open_bins_count > 3
    {
        score -= 3.5 * (1.0 - (bin_residual as f64 - item_size as f64) / 5.0) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (low post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual,
    // i.e. this bin can host a chain of two items.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Perfect chaining: next item exactly consumes what remains.
            if (next_item_size as u32) == post_residual {
                score -= 150.0;
            } else {
                // Partial chaining: reward proportional to how much of the
                // residual the next item would consume.
                let chain_fill = next / (post_residual as f64);
                score -= 80.0 * chain_fill;
            }
        } else {
            // Dead space for the next item: penalize proportionally to the
            // leftover gap that neither this nor the next item can use.
            let gap = next - (post_residual as f64);
            score += 0.5 * gap.min(40.0);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving less than the mean means we are tightening bins efficiently.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.8 * (mean_residual - pr).min(50.0);
    } else {
        score += 0.4 * (pr - mean_residual).min(50.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Early in the stream, encourage consolidation into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize opening a brand-new bin when decent fits exist,
    // unless the item is huge and residual is essentially fresh capacity.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    // MUTATION: sharpened the low tiers (0..8) and added an extra tier at 8..10,
    // since sub-10 leftovers are the dominant source of dead space in this stream.
    let dead = if post_residual < 2 { 12.5 } else if post_residual < 4 { 10.0 } else if post_residual < 6 { 8.2 } else if post_residual < 8 { 6.6 } else if post_residual < 10 { 5.4 } else if post_residual < 14 { 4.2 } else if post_residual < 20 { 2.8 } else if post_residual < 28 { 1.5 } else if post_residual < 40 { 0.7 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 270.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 210.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 58.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - (prf / cap);
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 16.0;
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) <= bin_capacity as u64 {
            let gap = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if gap <= 5 {
                score -= 20.0;
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && (item_size as u64 + next_item_size as u64) == bin_capacity as u64 {
            score -= 30.0;
        }
        if next_item_size > 0
            && (item_size as u64 + 2 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
        {
            score -= 24.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap_to_next = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += 1.8 * gap_to_next / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        if next_item_size > 0 && (item_size as u64 + 2 * next_item_size as u64) == bin_capacity as u64 {
            score -= 26.0 * (1.0 - 0.5 * progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.6 {
            score += 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf >= mean_residual {
            score -= 4.0 * (1.0 - progress) * (prf / cap).min(0.4);
        }
        // Fresh-bin economy: opening a bin is only worth it when the leftover
        // it strands is smaller than the average stranded slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream consolidation: prefer chain-friendly post-residuals.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
        // Scarcity-adjusted opening.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Pair-completion opening.
        if post_residual > 0 && (prf + mean_residual - cap).abs() <= 6.0 {
            score -= 11.0;
        }
        // Triple-chain opening.
        if next_item_size > 0
            && (item_size as u64 + 3 * next_item_size as u64) <= bin_capacity as u64
            && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
        {
            score -= 18.0 * (1.0 - 0.4 * progress);
        }
        // Stranded-leftover guard.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        // Residual-floor opening: penalize leftovers that overshoot widely.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 4.5 * overshoot * (0.5 + 0.5 * progress);
        }
        // Big-item fresh-bin preference.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 7.0 * (item_frac - 0.45) * 4.0 * (1.0 - progress);
        }
        // MUTATION: leftover-band targeting for fresh bins — when the fresh
        // bin's leftover falls in the "prime reuse band" (just at or above the
        // next item, within a small window), reward opening strongly; this
        // converts dead space into a scheduled drain rather than a waste.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 6 {
                score -= 8.0 * (1.0 - gap as f64 / 7.0) * (1.0 - 0.5 * progress);
            }
        }
        // MUTATION: dead-band avoidance for fresh bins — leftovers in the
        // 11..next_item band that are neither chainable nor near-mean are
        // the worst case; penalize their opening proportionally to how far
        // they sit below the next item.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual * 0.5 {
            score += 6.0 * (1.0 - prf / next_item_size as f64) * frag_index.clamp(0.0, 1.0);
        }
    }

    // Prefer tighter bins (small residual before placement), refined with fill ratio.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure: mildly penalize bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }

    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    if post_residual > 0 && post_residual < next_item_size && open_bins_count > 4 {
        score += 6.0;
    }

    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
        score -= 18.0;
    }

    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    if post_residual > 0 {
        let leftover_frac = prf / cap;
        let next_frac = next_item_size as f64 / cap;
        let mismatch = if next_item_size > 0 && post_residual >= next_item_size {
            0.0
        } else {
            (leftover_frac - next_frac).abs()
        };
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && post_residual < 25 {
            score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 && open_bins_count > 3 {
        score -= 3.0 * progress;
    }

    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 12.0 * (progress - 0.75) * 4.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 > 0 && rem2 as f64 <= mean_residual {
            score -= 4.0 * (1.0 - rem2 as f64 / cap);
        }
    }

    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Two-item lookahead closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let stranded = post_residual < next_item_size;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if stranded {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mid_gap = prf < mean_residual * 0.5 && prf > 4.0;
        if mid_gap {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    // MUTATION: sub-10 leftover drain bonus — small leftovers (1..10) are the
    // hardest to reuse later; when the next item can still fit into them,
    // give an extra compaction pull scaled by scarcity of fitting bins.
    if post_residual > 0 && post_residual < 10 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - post_residual as f64 / 10.0) * (1.0 + 1.0 / fitting_bins_count.max(1) as f64);
    }

    // MUTATION: mean-residual alignment pull — bins whose post-residual lands
    // close to the current mean residual are statistically most likely to be
    // drained by future items; reward that alignment mildly.
    if post_residual > 0 && mean_residual > 0.0 {
        let align = 1.0 - ((prf - mean_residual) / (mean_residual.max(1.0))).abs().min(1.0);
        score -= 3.0 * align * align * (1.0 - 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post_residual that cannot host typical items
    // (below the smallest plausible item) is wasted space.
    if post_residual < 10 {
        score += 45.0;
    }

    // Lookahead coupling: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
        // Bonus if post_residual is a "perfect pair" with the next item.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // current item is large (poor fit anywhere) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bin gets a base handicap so it only wins for genuinely bad fits.
        score += 30.0;
        score -= 40.0 * item_frac;          // large items justify fresh bins
        score -= 20.0 * progress;           // late stream: consolidation matters less
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;                  // fresh bin can serve the bigger next item
        }
        if open_bins_count == 0 {
            score -= 100.0;                 // must open a bin
        }
    } else {
        // Prefer reusing bins with larger residuals among equal fits (best-fit
        // would pick smallest, but leaving mid-size gaps wastes capacity).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Global pressure: many open bins with high mean residual -> encourage packing
    // into existing bins rather than fragmenting.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Base: prefer small post residual, with non-linear (quadratic) tightening
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (steeper quadratic)
    let prog_coupling = pr * (1.0 + 1.5 * progress) - 0.8 * progress * (pr * pr) / cap;
    score += 0.25 * prog_coupling;

    // Reward tight fits (small post_residual relative to capacity) more as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness.powf(3.0) * (0.5 + progress);

    // Lookahead: if the next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill_ratio = next_item_size as f64 / cap;
        score -= 6.0 * fill_ratio * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving awkward residual
        score += 3.0 * (pr / cap).powf(2.0);
    }

    // Penalize opening a new bin, more strongly early in the stream
    score += is_new * (20.0 + 25.0 * (1.0 - progress));

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 15.0;
    }

    // Mild penalty when bin residual is far below mean residual (fragmentation avoidance)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Slight preference for bins with more residual overall (keep big bins for big items)
    score += 0.03 * (bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Refined dead-space tiers with progress-scaled wall near zero.
    let dead = if post_residual < 3 { 10.4 } else if post_residual < 5 { 8.0 } else if post_residual < 8 { 6.6 } else if post_residual < 12 { 4.9 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Lookahead shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 240.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 7.0 * structure;
            if rem2 > 0 && rem2 < 10 {
                score += 24.0;
            }
            if rem2 <= 4 {
                score -= 10.0 + 7.0 * (1.0 - progress);
            }
            if rem2 % next_item_size.max(1) == 0 && rem2 / next_item_size.max(1) >= 2 {
                score -= 20.0;
            }
            if rem2 > 0 && rem2 as f64 <= mean_residual {
                score -= 5.0 * (1.0 - rem2 as f64 / cap);
            }
            if rem2 as f64 <= mean_residual * 1.5 && rem2 >= 1 {
                score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
            }
        } else {
            score += 8.0 * (next_item_size as f64 / cap) * (1.0 - prf / cap);
            score += 2.5 * (next_item_size - post_residual) as f64 / cap * (1.0 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }
    if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // Tight-bin preference.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.8 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 55.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 16 && open_bins_count > 6 {
        score += 9.0 + 5.0 * progress;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let waste_ratio = 1.0 - prf / cap;
        let fragmentation = frag_index.clamp(0.0, 1.0);
        let size_bias = item_frac * 34.0;
        score += 27.0 * waste_ratio - 15.0 * fragmentation - 22.0 * progress + size_bias;
        if open_bins_count > 8 && fragmentation > 0.5 {
            score -= 12.0;
        }
        if item_size <= 30 {
            score += 17.0;
        }
        if item_frac > 0.7 {
            score -= 18.0;
        }
        if item_frac > 0.5 && fragmentation > 0.35 {
            score -= 9.0;
        }
        if next_item_size > 0 {
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_capacity as u64 {
                score -= 34.0;
            } else if pair <= bin_capacity as u64 {
                let gap = bin_capacity as i64 - pair as i64;
                if gap <= 5 {
                    score -= 22.0;
                }
            }
            if item_size as u64 + 2 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 2 * next_item_size as u64) <= 8
            {
                score -= 26.0 * (1.0 - progress);
            }
            if item_size as u64 + 3 * next_item_size as u64 <= bin_capacity as u64
                && (bin_capacity as u64 - item_size as u64 - 3 * next_item_size as u64) <= 4
            {
                score -= 18.0 * (1.0 - 0.4 * progress);
            }
        }
        if next_item_size > 0 && (mean_residual as u32) < next_item_size && open_bins_count > 3 {
            score -= 9.0;
        }
        if post_residual > 0 && post_residual < 12 && open_bins_count > 2 {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
        if open_bins_count > 5 && mean_residual >= item_size as f64 {
            score += 10.0 * (mean_residual - item_size as f64) / cap;
        }
        if open_bins_count > 4 {
            let slack_per_bin = mean_residual / open_bins_count as f64;
            if slack_per_bin > item_size as f64 * 1.5 {
                score += 14.0 * (slack_per_bin / cap).min(0.5);
            }
        }
        if post_residual > 0 {
            let pair_gap = ((prf + mean_residual) - cap).abs();
            score += 3.0 * pair_gap / cap;
            if pair_gap <= 6.0 {
                score -= 11.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - prf / next_item_size as f64);
            let strandedness = 1.0 - prf / next_item_size as f64;
            score += 10.0 * strandedness * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size == 0 {
            score -= 10.0 * (1.0 - progress);
        }
        if post_residual > 0 && prf < mean_residual * 0.8 && open_bins_count > 3 {
            score += 12.0 * (1.0 - (prf / mean_residual).min(1.0));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            if chain_gap as f64 >= mean_residual {
                score -= 7.0 * (1.0 - progress);
            }
            let overshoot = (prf - next_item_size as f64) / cap;
            score += 4.5 * overshoot * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 4 && item_frac < 0.4 {
            score += 7.0 * (1.0 - item_frac);
        }
        // Scarcity-adjusted opening.
        if fitting_bins_count <= 2 {
            score -= 14.0 * (1.0 - progress);
        } else if fitting_bins_count >= 5 {
            score += 6.0 + 4.0 * (open_bins_count.min(20) as f64 / 20.0);
        }
        // Big-item fresh-bin preference.
        if item_size as f64 > mean_residual * 1.3 && item_frac > 0.45 {
            score -= 28.0 * (item_frac - 0.45) * (1.0 - progress);
        }
        // Fresh-bin economy: penalize bins stranding worse-than-average slack.
        if post_residual > 0 && prf > mean_residual * 1.2 && open_bins_count > 5 {
            score += 9.0 * ((prf - mean_residual) / cap).min(0.5);
        }
        // Early-stream chain-friendly leftovers.
        if post_residual > 0 && progress < 0.4 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Mid-band shaping.
    if post_residual >= 31 && post_residual <= 49 {
        score += 7.0 * (1.0 - progress);
    }

    // Reusable small residuals.
    if post_residual == 10 || post_residual == 15 || post_residual == 20 || post_residual == 30 {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Late-stream exactness push.
    if progress > 0.75 && post_residual > 0 {
        score += (prf / cap) * 48.0 * (progress - 0.75);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 24.0 * (progress - 0.75);
        }
    }
    // Endgame zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 80.0 * (prf / cap) * (progress - 0.85);
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 180.0 * (progress - 0.85);
        }
    }

    // Global waste pressure.
    if post_residual > 0 && progress > 0.4 {
        score += (prf / cap) * 6.0 * (progress - 0.4);
    }

    // Mid-band stranding under high spread.
    if post_residual > 15 && post_residual < 35 && open_bins_count > 6 {
        let spread = ((mean_residual - prf) / cap).abs();
        score += 5.0 * spread * (0.5 + 0.5 * progress);
    }

    // Composable residual shaping.
    if fitting_bins_count > 2 && post_residual > 0 {
        let half = cap / 2.0;
        let dist = ((prf - half) / half).abs();
        score += 4.0 * dist;
    }

    // Close out nearly-full bins late.
    if post_residual > 0 && post_residual <= 3 && progress > 0.6 {
        score -= 10.0;
    }

    // Waste-floor guard for near-exact fills.
    if post_residual == 1 || post_residual == 2 {
        score -= 9.0 + 7.0 * (1.0 - progress);
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += (prf / cap) * 3.0 / fitting_bins_count as f64;
    }

    // Small-gap value scaling.
    if post_residual > 0 && post_residual < 8 && next_item_size > post_residual {
        score += 14.0 * (1.0 - progress);
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 6.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Squander guard: strand-mismatch penalty scaled by fragmentation.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / next_item_size as f64).min(1.0));
    }

    // Residual-pool absorption check.
    if post_residual > 0 && open_bins_count > 6 && prf < mean_residual * 0.5 {
        score += 4.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Next-item mismatch penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if post_residual < next_item_size {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.5 && prf > 4.0 {
        score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Mid-gap stranding under scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    // Near-miss closure reward.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 4 {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Overshoot remnant shaping.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 10 {
            score -= 5.0 * (1.0 - progress);
        } else if rem2 > 0 {
            score += 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
