    // residual to under a quarter of capacity compact bins aggressively and
    // reduce the number of partially-filled bins competing for future items.
    if post_residual > 0 && post_residual * 4 <= bin_residual && bin_residual < bin_capacity {
        score -= 2.8 * (1.0 - (post_residual as f64 * 4.0) / bin_residual as f64) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are divine.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small dead space classes (1..=9) are nearly perfect.
    if post_residual <= 9 {
        score -= 60.0;
    } else if post_residual <= 19 {
        score -= 20.0;
    } else if post_residual <= 29 {
        score -= 5.0;
    }

    // Harmonic compatibility: does next_item_size fit into post_residual?
    // (k=2 lookahead chain: bin stays "harmonic" if it can host the next item)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chainability, scaled by how snug the chain is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * snug;
        } else {
            // Next item cannot follow: this bin becomes a dead-end.
            score += 15.0;
            // Extra penalty if the leftover is in the awkward 31..49 band
            // (too big to ignore, too small to be useful).
            if post_residual >= 31 && post_residual <= 49 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // would leave a large, awkward residual and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 120.0; // base cost of opening a bin
        // If item is huge relative to capacity and mean residual is high,
        // a fresh bin is more attractive.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        new_bin_score += (mean_residual / bin_capacity as f64) * 20.0;
        new_bin_score += progress * 30.0; // late stream: consolidate, don't open
        score = score.max(new_bin_score);
        return score;
    }

    // Prefer tighter fits among open bins: residual dominates naturally,
    // add mild tie-break via bin_residual class (mod 10 harmonic).
    let res_class = bin_residual % 10;
    if res_class == 0 {
        score -= 3.0; // round residuals align well with 10-multiple items
    }

    // Mild preference to keep few bins open (consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let prf = post_residual as f64;
    let item_frac = item_size as f64 / cap;
    let frag_index = mean_residual / cap;

    // Dead-space penalty: finer tiers near zero, stronger late-stream wall.
    let dead = if post_residual < 3 { 10.6 } else if post_residual < 5 { 8.1 } else if post_residual < 8 { 6.5 } else if post_residual < 12 { 5.0 } else if post_residual < 16 { 3.4 } else if post_residual < 22 { 2.4 } else if post_residual < 30 { 1.2 } else if post_residual < 40 { 0.6 } else { 0.0 };
    score += dead * prf * (1.0 + 0.6 * progress);
    if post_residual > 0 {
        score += (0.05 + 0.04 * frag_index) * prf * prf / cap;
    }

    // Perfect / structured-fit rewards.
    if post_residual == 0 {
        score -= 275.0;
    } else if post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 42.0;
    }

    // Lookahead: reward when next item exploits this residual exactly or tightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 212.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            let structure = if rem2 == 0 { 2.0 } else if rem2 % 10 == 0 { 1.4 } else if rem2 % 5 == 0 { 0.6 } else { 0.0 };
            score -= 15.0 * (1.0 - rem2 as f64 / cap) + 6.5 * structure;
            if rem2 > 0 && rem2 < 10 {
