    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the leftover capacity.
        let waste_ratio = next_item_size as f64 / post_residual as f64;
        score += 8.0 * waste_ratio.min(3.0);
    }

    // Penalize leaving residual far below mean residual (fragmenting a rich bin).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is huge and would leave bad fit elsewhere.
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Late in stream: tighten packing, prefer fuller bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
