    // Global waste pressure — tighten late-stream compaction.
    if post_residual > 0 && progress > 0.4 {
        score += prf / cap * 6.0 * (progress - 0.4);
    }

    // Fragmentation-aware tight-fit scaling.
    if fitting_bins_count >= 2 && post_residual > 0 {
        score += prf / cap * 3.0 / fitting_bins_count as f64;
    }

    // Dead-space trap detection.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf > mean_residual {
        score += 5.0 * (1.0 + progress);
    }

    // Compaction pull toward exact closure under scarce fits.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 <= 12 {
            score -= 4.0 + 5.0 * (1.0 - rem2 as f64 / 12.0);
        }
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if post_residual < next_item_size {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < mean_residual * 0.5 && prf > 4.0 {
        score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Fragmentation-aware squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / (next_item_size as f64)).min(1.0));
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Two-item lookahead closure: residuals absorbable into portfolio slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 >= 1 && rem2 as f64 <= mean_residual * 1.5 {
            score -= 3.5 * (1.0 - rem2 as f64 / (mean_residual * 1.5 + 1.0));
        }
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Variance-aware tightness.
    if frag_index > 0.45 && post_residual > 0 {
        score += 4.0 * frag_index * (prf / cap);
    }

    // Small stranded leftovers under scarcity.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 4.0 * (1.0 - prf / 25.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small dead space) with non-linear penalty
    let pr = post_residual as f64;
    score += pr * pr / (bin_capacity as f64 * 2.0);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving dead space the next item cannot use
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize placing into bins when many bins fit (prefer spreading toward best fit)
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Time horizon: early in stream, be more conservative (favor new bins for large items);
    // late in stream, fill open bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Global state coupling: high mean residual means open bins are roomy;
    // prefer filling them rather than opening new bins
    score -= mean_residual * 0.15;

    // Many open bins: discourage opening another
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate logic: empty bin gets base cost; make it attractive only
    // when item is large relative to capacity or residuals are tight
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let tight_state = (mean_residual < item_size as f64) as f64;
        score = 45.0 + large_item * 40.0 - tight_state * 30.0 - progress * 15.0
              - (post_residual as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 80.0; // don't open new bin when an existing bin is last chance
        }
    }

    score
}

