        score += 4.0 * frag_index * (prf / cap);
    }

    // Squander guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && prf < cap * 0.5 && frag_index > 0.3 {
        score += 6.0 * frag_index * (1.0 - (prf / next_item_size as f64).min(1.0));
    }

    // Residual-pool absorption check.
    if post_residual > 0 && open_bins_count > 6 && prf < mean_residual * 0.5 {
        score += 4.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0));
    }

    // Mid-stream exact-closure sweep.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && prf >= mean_residual * 0.9 && prf <= mean_residual * 1.4 {
        score -= 3.0 * (1.0 - ((prf - mean_residual) / (mean_residual.max(1.0) * 0.5)).abs().min(1.0));
    }

    // Endgame exactness.
    if progress > 0.7 && next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 == 0 {
            score -= 12.0;
        } else if rem2 < 6 {
            score -= 6.0 * (1.0 - rem2 as f64 / 6.0);
        }
    }

    // Residual-continuity reward.
    if post_residual > 0 {
        let nearness = 1.0 - ((prf - mean_residual) / cap).abs().min(1.0);
        score -= 2.5 * nearness * (1.0 - progress);
    }

    // Two-step chain closure reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        if rem2 % next_item_size == 0 {
            score -= (2.0 + 3.0 * frag_index) * (1.0 - progress);
        }
    }

    // Next-item mismatch penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let mismatch = (prf / cap - next_item_size as f64 / cap).abs();
        score += 9.0 * mismatch * (1.0 - 0.5 * progress);
    }

    // Scarcity-weighted leftover penalty.
    if post_residual > 0 && next_item_size > 0 {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        if post_residual < next_item_size {
            score += 8.0 * scarcity * (1.0 - prf / next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 6.0 * scarcity;
        }
    }

    // Mid-gap dead-zone penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        if prf < mean_residual * 0.5 && prf > 4.0 {
            score += 5.0 * (1.0 - prf / (mean_residual * 0.5 + 1.0)) * (0.4 + 0.6 * progress);
        }
    }

    // Tight-bin conservation.
    if post_residual > 0 && bin_residual as f64 <= mean_residual * 0.6 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - bin_residual as f64 / cap) * (1.0 - progress);
    }

    // Exact-fill sweep refinement.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let mult = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && mult >= 2 && mult <= 3 {
            score -= 6.0 * (1.0 - progress) + 2.0 * frag_index;
        }
    }

    // Late-stream zero-waste drive.
    if progress > 0.85 && post_residual > 0 && bin_residual < bin_capacity {
        score += 4.0 * (prf / cap) * (progress - 0.85) * 20.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 3 {
            score -= 9.0 * (progress - 0.85) * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space with a non-linear (quadratic) term.
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    let progress_coupling = 1.0 + 1.2 * progress * (1.0 - progress) * 4.0 * (pr / cap);
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item fill ratio.
    let fill = it / cap;
    score -= 30.0 * fill * fill * (1.0 - (pr / cap).powi(2)).max(0.0);

    // Penalize bins whose residual deviates from the mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize blocking the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 20.0 * waste * waste;
        // Reward leaving exactly room for the next item.
        let exact = (pr - nx).abs() / cap;
        score -= 12.0 * (1.0 - exact.min(1.0));
    }

    // Mild penalty for proliferating open bins, scaled by progress.
    score += 2.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
