    if fitting_bins_count <= 2 {
        score -= 4.0;
    }

    // Tight-bin preference with fill-ratio shaping.
    let tight = bin_residual as f64 / cap;
    score += 2.3 * tight - 1.1 * tight * tight;

    // Balance pressure.
    if bin_residual as f64 > mean_residual {
        score += 1.3;
    }
    if open_bins_count > 10 {
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += 2.5 * dev;
    }

    // Small unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
