            score += 5.5 * bump * (prf / cap) * (0.6 + 0.8 * progress);
        }
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem2 = post_residual - next_item_size;
        let diff = (rem2 as f64 - mean_residual).abs();
        if diff <= 2.0 {
            score -= 7.0 * (1.0 - diff / 3.0) * (1.0 - 0.5 * progress);
        }
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 3 {
        score += 6.0 * (1.0 - prf / next_item_size as f64) * (1.0 - progress);
    }

    // Bin-drain priority — flush nearly-full bins early when many compete.
    if bin_residual < bin_capacity && open_bins_count > 3 {
        let fill_rank = 1.0 - (bin_residual as f64 / mean_residual.max(1.0)).min(1.0);
        score -= 3.5 * fill_rank * (0.4 + 0.6 * progress) * (1.0 - item_frac);
    }

    // Residual-split guard — avoid chopping a usable residual into two
    // fragments neither of which hosts the next item.
    if post_residual > 0 && next_item_size > 0 && bin_residual > next_item_size * 2 {
        if post_residual < next_item_size && bin_residual - item_size < next_item_size {
            score += 4.5 * (1.0 - progress) * (1.0 - item_frac);
        }
    }

    // Capacity-aware leftover value — leftovers consumable by items of the
    // typical scale are assets; discount the generic dead-space penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 4 {
        score -= 3.0 * (1.0 - progress) * (prf / cap).min(0.3);
    }

    // MUT: compaction sweep — with many open bins, prefer the bin whose
    // post-residual lands closest to a small multiple of the next item so
    // the leftover is guaranteed drainable, reducing scattered dead space.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 6 {
        let rem2 = post_residual % next_item_size;
        if rem2 <= 2 {
            score -= 5.0 * (1.0 - rem2 as f64 / 3.0) * (0.5 + 0.5 * progress);
        }
    }

    // MUT: late-stream mean-residual drain — in the final third, favor
    // bins whose post-residual stays within one mean-residual of zero so
    // remaining items can finish them instead of opening fresh bins.
    if progress > 0.66 && post_residual > 0 && prf <= mean_residual {
        score -= 3.0 * (1.0 - prf / (mean_residual + 1.0)) * (progress - 0.66) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
